window.QUESTIONS=[{"id": "ch2-1", "ch": "ch2", "num": 1, "q": "WHEN YOU SEE THIS SIGN, YOU MUST:", "opts": ["Stop completely, check for pedestrians, and cross traffic", "Slow down without coming to a complete stop", "Stop completely and wait for a green light", "Slow down and check for traffic"], "ans": 0, "img": "img/ch2-1.png", "qz": "看到这个标志，你必须：", "oz": ["完全停车，查看行人和横向车流", "减速但不用完全停下", "完全停车并等绿灯", "减速并查看车流"], "story": "小兔子开车看到红红的八角形牌子，“咦，这是STOP！”她把车稳稳停住，左看看右看看，等斑马线上的小鸭子走过去，横路上也没车了，才慢慢开走。不用等绿灯哦，因为这里根本没有灯～", "tip": "八角红牌=停到底，看人看车再出发", "tricky": false}, {"id": "ch2-2", "ch": "ch2", "num": 2, "q": "THIS IS THE SHAPE AND COLOR OF A __________ SIGN.", "opts": ["Stop", "Wrong Way", "Yield", "Do not enter"], "ans": 2, "img": "img/ch2-2.png", "qz": "这是________标志的形状和颜色。", "oz": ["停车", "逆行", "让行", "禁止驶入"], "story": "小熊看到一个倒过来的三角形，红边白肚子，像一块倒着的三角蛋糕🍰。熊妈妈说：“倒三角就是YIELD让一让，别人先走，你再走。”", "tip": "倒三角=让一让", "tricky": true}, {"id": "ch2-3", "ch": "ch2", "num": 3, "q": "THIS SIGN MEANS:", "opts": ["Stop", "No U-Turn", "Yield", "Do not enter"], "ans": 3, "img": "img/ch2-3.png", "qz": "这个标志的意思是：", "oz": ["停车", "禁止掉头", "让行", "禁止驶入"], "story": "小狐狸开到一个路口，看到红圆圈里一道白横杠，像嘴巴被封住：“不许进！”原来这是单行道的出口，进去就会和别人撞脸，小狐狸乖乖绕路啦。", "tip": "红圈白横杠=不许进", "tricky": true}, {"id": "ch2-4", "ch": "ch2", "num": 4, "q": "THIS SIGN MEANS:", "opts": ["No U-Turn", "No Turning", "No left turn", "No right turn"], "ans": 0, "img": "img/ch2-4.png", "qz": "这个标志的意思是：", "oz": ["禁止掉头", "禁止转弯", "禁止左转", "禁止右转"], "story": "小猪想在路上画个“U”字掉头，可牌子上一个U形箭头被红线划掉了。“哦～不许U-turn！”小猪就往前开到能掉头的地方再转。", "tip": "U形箭头被划掉=禁止掉头", "tricky": true}, {"id": "ch2-5", "ch": "ch2", "num": 5, "q": "THIS SIGN MEANS:", "opts": ["No U-Turn", "No left turn", "No right turn", "No turning"], "ans": 2, "img": "img/ch2-5.png", "qz": "这个标志的意思是：", "oz": ["禁止掉头", "禁止左转", "禁止右转", "禁止转弯"], "story": "小松鼠看牌子：箭头往右拐，还被红斜线打了叉。“右边不能拐呀！”小松鼠就直直往前开，找下一个路口。", "tip": "箭头往哪边被划=哪边不许转", "tricky": true}, {"id": "ch2-6", "ch": "ch2", "num": 6, "q": "THIS SIGN MEANS:", "opts": ["You must turn left or right", "You are approaching a T-intersection", "The road that you are on intersects with a divided highway", "Designates an overpass above a divided highway"], "ans": 2, "img": "img/ch2-6.png", "qz": "这个标志的意思是：", "oz": ["你必须左转或右转", "你正接近T字路口", "你所在的道路与一条中间有隔离带的公路相交", "表示上方有跨越分隔公路的天桥"], "story": "小乌龟看到白牌子写着DIVIDED HIGHWAY，中间画着一条被隔开的粗马路，自己这条小路竖着穿过去。“原来前面要和一条有隔离带的大路交叉呀！”", "tip": "DIVIDED HIGHWAY横着画=前方与分隔公路相交", "tricky": true}, {"id": "ch2-7", "ch": "ch2", "num": 7, "q": "YOU NEED TO USE EXTRA CAUTION WHEN DRIVING NEAR A PEDESTRIAN USING A WHITE CANE BECAUSE:", "opts": ["He or she is deaf", "He or she has a mental disability", "He or she is blind", "He or she has a walking problem"], "ans": 2, "qz": "在使用白手杖的行人附近开车要格外小心，因为：", "oz": ["他/她是聋人", "他/她有智力障碍", "他/她是盲人", "他/她行走不便"], "story": "小兔子看到一位老爷爷拿着白白的手杖，一点一点探路。兔妈妈说：“白手杖是眼睛看不见的人用的，他看不到你的车，你要替他看着哦。”", "tip": "白手杖=看不见，要让着", "tricky": false}, {"id": "ch2-8", "ch": "ch2", "num": 8, "q": "WHEN DRIVING NEAR A BLIND PEDESTRIAN WHO IS CARRYING A WHITE CANE OR USING A GUIDE DOG, YOU SHOULD:", "opts": ["Slow down and be prepared to stop", "Take the right-of-way", "Proceed normally", "Drive away quickly"], "ans": 0, "qz": "在拿白手杖或带导盲犬的盲人附近开车时，你应该：", "oz": ["减速并准备停车", "抢先通行", "正常行驶", "快速开走"], "story": "小熊看到导盲犬汪汪带着盲人阿姨过马路，小熊马上松油门、脚放刹车上：“慢慢来，我等你们～”", "tip": "看到导盲犬白手杖：慢下来，准备停", "tricky": false}, {"id": "ch2-9", "ch": "ch2", "num": 9, "q": "IF THERE ARE NO SIGNALS AT A RAILROAD CROSSING, YOU SHOULD:", "opts": ["Slow down and prepare to stop if you see or hear a train approaching", "Proceed as quickly as possible over the tracks", "Proceed through the crossing at a normal rate", "Proceed slowly over the tracks"], "ans": 0, "qz": "如果铁路道口没有信号灯，你应该：", "oz": ["减速，如看到或听到火车接近准备停车", "尽快通过铁轨", "以正常速度通过道口", "慢慢开过铁轨"], "story": "小鸭子来到没有灯也没有栏杆的铁轨前，竖起耳朵听“呜——”，睁大眼睛看两边。没火车才过，有火车就乖乖停。", "tip": "没灯的铁轨：慢、看、听、准备停", "tricky": false}, {"id": "ch2-10", "ch": "ch2", "num": 10, "q": "YOU MAY DRIVE AROUND THE GATES AT A RAILROAD CROSSING:", "opts": ["When the train has passed", "Never", "When the lights have stopped flashing", "When other drivers drive around the gates"], "ans": 1, "qz": "你可以绕过铁路道口的栏杆：", "oz": ["火车过去之后", "永远不行", "灯停止闪烁时", "别的司机绕过去时"], "story": "小狐狸看到栏杆放下来，火车刚过去，它想偷偷绕过去。狐狸爸爸说：“不行！可能还有第二列火车藏在后面！”栏杆没抬起来，永远不能绕。", "tip": "栏杆放下=永远不绕", "tricky": true}, {"id": "ch2-11", "ch": "ch2", "num": 11, "q": "IF YOU SEE THIS SIGN ABOVE YOUR LANE, YOU:", "opts": ["May not exit the freeway in this lane", "May continue through the interchange or exit the freeway in this lane", "May stay in this lane and continue through the interchange", "Must exit the freeway if you stay in this lane"], "ans": 3, "img": "img/ch2-11.png", "qz": "如果你在车道上方看到这个标志，你：", "oz": ["不能在此车道驶出高速", "可以在此车道直行或驶出", "可以留在此车道直行通过立交", "如果留在此车道就必须驶出高速"], "story": "小猫看到车道头顶的绿牌子下面有黄色小条写着EXIT ONLY。“ONLY就是‘只能’！待在这条道就只能出去啦。”不想出去就要早点换道。", "tip": "黄色EXIT ONLY=这条道只能出", "tricky": true}, {"id": "ch2-12", "ch": "ch2", "num": 12, "q": "HIGHWAY AND EXPRESSWAY GUIDE SIGNS ARE:", "opts": ["Orange with black letters", "Green with white letters", "Yellow with black letters", "Red with white letters"], "ans": 1, "qz": "高速公路和快速路的指路标志是：", "oz": ["橙底黑字", "绿底白字", "黄底黑字", "红底白字"], "story": "小兔子在高速上看到大大的绿牌子白字，写着城市名字和出口号。“绿色像森林地图，带我回家！”", "tip": "绿底白字=指路", "tricky": false}, {"id": "ch2-13", "ch": "ch2", "num": 13, "q": "THIS SIGN IS USED TO WARN DRIVERS ABOUT:", "opts": ["Upcoming intersections", "Road construction", "Road curves ahead", "Changes in traffic lanes"], "ans": 2, "img": "img/ch2-13.png", "qz": "这个标志用来警告司机：", "oz": ["前方路口", "道路施工", "前方弯道", "车道变化"], "story": "小乌龟看到黄菱形牌子上一个弯弯箭头，“前面路要拐弯啦！”于是提前慢慢开。", "tip": "黄菱形弯箭头=前方有弯", "tricky": false}, {"id": "ch2-14", "ch": "ch2", "num": 14, "q": "THIS SIGN TELLS YOU THAT:", "opts": ["No turns are allowed on this road", "The road narrows ahead", "There are a series of curves ahead", "The road may be slippery when wet"], "ans": 2, "img": "img/ch2-14.png", "qz": "这个标志告诉你：", "oz": ["此路禁止转弯", "前方道路变窄", "前方有连续弯道", "路湿时可能打滑"], "story": "小蛇看到牌子上箭头扭来扭去像自己的身体🐍：“前面是一串弯弯！”要慢慢扭过去哦。", "tip": "扭扭箭头=连续弯", "tricky": true}, {"id": "ch2-15", "ch": "ch2", "num": 15, "q": "THIS SIGN MEANS:", "opts": ["Left curve ahead", "Series of curves", "S curved ahead", "Slippery when wet"], "ans": 3, "img": "img/ch2-15.png", "qz": "这个标志的意思是：", "oz": ["前方左弯", "连续弯道", "前方S弯", "路湿易滑"], "story": "小猪看到牌子上一辆小车后面拖着两条歪歪扭扭的线，像车子在跳舞打滑。“下雨时路会滑滑的！”", "tip": "小车+歪歪线=湿滑", "tricky": true}, {"id": "ch2-16", "ch": "ch2", "num": 16, "q": "THIS SIGN INDICATES THAT:", "opts": ["There is a steep hill ahead", "No trucks are allowed on the hill", "A logging road is ahead", "There are trucks on the hill"], "ans": 0, "img": "img/ch2-16.png", "qz": "这个标志表示：", "oz": ["前方有陡坡", "坡上禁止卡车", "前方是伐木路", "坡上有卡车"], "story": "小熊看到牌子上小卡车站在斜斜的三角上，像在滑滑梯。“前面有大陡坡！”要用低速档慢慢下。", "tip": "卡车站斜坡=陡坡", "tricky": true}, {"id": "ch2-17", "ch": "ch2", "num": 17, "q": "A YELLOW AND BLACK DIAMOND-SHAPED SIGN:", "opts": ["Warns you about conditions on or near the road", "Helps direct you to cities and towns ahead", "Tells you about traffic laws and regulations", "Tells you about road construction ahead"], "ans": 0, "qz": "黄黑菱形的标志：", "oz": ["警告你道路上或附近的情况", "指引你前往前方城镇", "告诉你交通法规", "告诉你前方道路施工"], "story": "小兔子学颜色：黄色菱形像一个提醒小喇叭📣，“小心哦，前面有情况！”橙色才是施工，绿色才是指路。", "tip": "黄菱形=警告", "tricky": false}, {"id": "ch2-18", "ch": "ch2", "num": 18, "q": "THE SIGN WITH THIS SHAPE AND COLOR IS A _____________ SIGN.", "opts": ["No passing zone", "Wrong way", "Railroad crossing", "Stop"], "ans": 0, "img": "img/ch2-18.png", "qz": "这种形状和颜色的标志是________标志。", "oz": ["禁止超车区", "逆行", "铁路道口", "停车"], "story": "小狐狸看到一个横躺的黄色三角旗（尖尖朝右），放在马路左边。“这是‘不许超车’小旗子！”它是唯一长这样的牌子。", "tip": "横着的三角旗=禁止超车", "tricky": true}, {"id": "ch2-19", "ch": "ch2", "num": 19, "q": "WHICH OF THESE SIGNS IS USED TO SHOW THE END OF A DIVIDED HIGHWAY?", "opts": ["2", "4", "3", "1"], "ans": 0, "img": "img/ch2-19.png", "qz": "下面哪个标志表示分隔公路的结束？", "oz": ["2", "4", "3", "1"], "story": "小鸭子看四个牌子：2号牌子里，中间的隔离岛圆圆地收拢，两边箭头合到一起变成双向路——“分开的路结束啦，前面对面有车来！”注意选项A才是“2”哦。", "tip": "隔离岛收尾、箭头一上一下=分隔路结束", "tricky": true}, {"id": "ch2-20", "ch": "ch2", "num": 20, "q": "THIS SIGN IS USED TO WARN DRIVERS ABOUT:", "opts": ["Lane ends, merge left", "Road curves ahead", "Upcoming intersections", "Road construction"], "ans": 0, "img": "img/ch2-20.png", "qz": "这个标志用来警告司机：", "oz": ["车道结束，向左并道", "前方弯道", "前方路口", "道路施工"], "story": "小猫看到牌子上右边的线断了，往左边靠拢。“右车道没有了，要向左并进去！”", "tip": "一条线断掉弯过去=车道结束要并道", "tricky": true}, {"id": "ch2-21", "ch": "ch2", "num": 21, "q": "THIS SIGN SHOWS ONE TYPE OF:", "opts": ["Intersection", "Road curve", "Right turn", "Lane change"], "ans": 0, "img": "img/ch2-21.png", "qz": "这个标志表示一种：", "oz": ["路口", "弯道", "右转", "变道"], "story": "小松鼠看到黄牌子上一个大十字✚：“这是十字路口！”横着竖着都有车会来哦。", "tip": "十字=路口", "tricky": false}, {"id": "ch2-22", "ch": "ch2", "num": 22, "q": "THIS SIGN SHOWS ONE TYPE OF:", "opts": ["Right turn", "Intersection", "Lane change", "Road curve"], "ans": 1, "img": "img/ch2-22.png", "qz": "这个标志表示一种：", "oz": ["右转", "路口", "变道", "弯道"], "story": "小兔子看到牌子上像一个“T”或“侧边小路”的图案，“这也是路口的一种哦！”只要画着路和路连在一起，就是路口。", "tip": "路连路的图案=路口", "tricky": true}, {"id": "ch2-23", "ch": "ch2", "num": 23, "q": "WHAT SHOULD YOU BE MOST CONCERNED ABOUT WHEN YOU SEE THIS SIGN?", "opts": ["Driving with your headlights out of alignment because one side of your car is higher than the other", "Damaging a tire, if you drift onto the shoulder", "Hydroplaning, if the shoulder has water on it", "Losing control of your vehicle, if you drift onto the shoulder, because of a drop off"], "ans": 3, "img": "img/ch2-23.png", "qz": "看到这个标志时，你最应该担心什么？", "oz": ["车一边高一边低导致大灯偏", "开到路肩上扎坏轮胎", "路肩有水会打滑", "开到路肩时因为落差导致失控"], "story": "小乌龟看到牌子上一辆小车一边轮子掉到路边、车身歪歪的——原来路肩比路面矮一截。“万一轮子掉下去，车会一歪就失控！”所以要稳稳握好方向盘。", "tip": "路肩低=掉下去会失控", "tricky": true}, {"id": "ch2-24", "ch": "ch2", "num": 24, "q": "WHAT IS THE MEANING OF THIS SIGN?", "opts": ["The traffic signal ahead is red", "The traffic signal ahead is broken", "The traffic signal ahead is green", "There is a traffic signal ahead"], "ans": 3, "img": "img/ch2-24.png", "qz": "这个标志是什么意思？", "oz": ["前方信号灯是红灯", "前方信号灯坏了", "前方信号灯是绿灯", "前方有信号灯"], "story": "小熊看到黄牌子上画着红黄绿三个圆，“它不告诉你现在是什么颜色，只是说：前面有红绿灯哦！”", "tip": "画个红绿灯=前方有灯", "tricky": true}, {"id": "ch2-25", "ch": "ch2", "num": 25, "q": "THIS SIGN MEANS:", "opts": ["Divided highway ends", "One-way street begins", "One-way street ends", "Divided highway begins"], "ans": 3, "img": "img/ch2-25.png", "qz": "这个标志的意思是：", "oz": ["分隔公路结束", "单行道开始", "单行道结束", "分隔公路开始"], "story": "小狐狸看到牌子上的路中间突然长出一个隔离小岛，两边箭头分开走。“路被分开啦，分隔公路开始！”和19题的“合拢”正好相反。", "tip": "中间长出小岛=分隔路开始", "tricky": true}, {"id": "ch2-26", "ch": "ch2", "num": 26, "q": "FROM TOP TO BOTTOM, THE FOLLOWING IS THE PROPER ORDER FOR TRAFFIC LIGHTS:", "opts": ["Red, yellow, green", "Red, green, yellow", "Green, red, yellow", "Green, yellow, red"], "ans": 0, "qz": "信号灯从上到下的正确顺序是：", "oz": ["红、黄、绿", "红、绿、黄", "绿、红、黄", "绿、黄、红"], "story": "小兔子抬头看：红灯在最上面像戴帽子🍎，黄在中间像肚子🍋，绿在最下面像鞋子🥒。色盲的朋友也能靠位置认灯！", "tip": "红黄绿从上到下", "tricky": false}, {"id": "ch2-27", "ch": "ch2", "num": 27, "q": "IF A GREEN ARROW TURNS INTO A GREEN LIGHT, YOU:", "opts": ["May still turn but you must yield to oncoming traffic", "May no longer turn and must proceed straight", "Still have the right of way to turn", "No longer have to turn the way the arrow indicates"], "ans": 0, "qz": "如果绿色箭头变成绿色圆灯，你：", "oz": ["仍可以转弯，但必须让对向来车", "不能再转弯，只能直行", "仍然拥有转弯优先权", "不必再按箭头方向转"], "story": "小猫在等左转，绿箭头时它是“VIP先走”；箭头变成普通绿灯，小猫还能转，但要先让对面直行的小狗过去。", "tip": "箭头变圆灯=能转但要让", "tricky": true}, {"id": "ch2-28", "ch": "ch2", "num": 28, "q": "A STEADY YELLOW LIGHT AT AN INTERSECTION MEANS:", "opts": ["Go", "Yield to other cars", "Slow down and prepare to stop", "Stop"], "ans": 2, "qz": "路口的稳定黄灯表示：", "oz": ["走", "让其他车", "减速准备停车", "停车"], "story": "小鸭子看到黄灯亮了，“红灯马上要来啦～”慢慢减速准备停下，不是抢着冲哦。", "tip": "黄灯=快变红，准备停", "tricky": false}, {"id": "ch2-29", "ch": "ch2", "num": 29, "q": "A FLASHING YELLOW LIGHT MEANS THAT YOU SHOULD:", "opts": ["Slow down and proceed with care", "Continue through if the way is clear", "Stop and proceed when a green light appears", "Stop and proceed when the way is clear"], "ans": 0, "qz": "闪烁的黄灯表示你应该：", "oz": ["减速并小心通过", "路畅通就继续通过", "停车等绿灯再走", "停车，路畅通再走"], "story": "小熊看到黄灯一闪一闪像萤火虫，“这是提醒我小心哦”，它减速看一看，不用停，小心开过去。", "tip": "闪黄=慢点小心走", "tricky": true}, {"id": "ch2-30", "ch": "ch2", "num": 30, "q": "YOU MUST STOP WHEN YOU SEE A:", "opts": ["Flashing red light", "Steady yellow light", "Yellow arrow", "Flashing yellow light"], "ans": 0, "qz": "看到以下哪种时必须停车？", "oz": ["闪烁红灯", "稳定黄灯", "黄色箭头", "闪烁黄灯"], "story": "小兔子看到红灯一闪一闪，“闪红就像STOP牌！”先停下来，看清楚了再走。", "tip": "闪红=STOP牌", "tricky": false}, {"id": "ch2-31", "ch": "ch2", "num": 31, "q": "A STEADY GREEN LIGHT AT AN INTERSECTION MEANS THAT YOU:", "opts": ["Must slow down and prepare to stop", "Must stop and check for oncoming traffic before proceeding", "May drive through the intersection if the road is clear", "May not turn right"], "ans": 2, "qz": "路口稳定绿灯表示你：", "oz": ["必须减速准备停车", "必须停车查看来车再走", "路面畅通时可以通过路口", "不能右转"], "story": "小猪看到绿灯，开心地说“可以走啦！”但还是瞄一眼路口里有没有小朋友和车，没有才通过。", "tip": "绿灯=路空就可以走", "tricky": false}, {"id": "ch2-32", "ch": "ch2", "num": 32, "q": "A STEADY YELLOW LIGHT MEANS THAT A _______ LIGHT WILL SOON APPEAR.", "opts": ["Flashing yellow", "Steady green", "Steady red", "Flashing red"], "ans": 2, "qz": "稳定黄灯表示________灯即将出现。", "oz": ["闪烁黄", "稳定绿", "稳定红", "闪烁红"], "story": "小松鼠记顺序：绿→黄→红，黄灯后面跟着的就是红灯大哥。", "tip": "黄后是红", "tricky": false}, {"id": "ch2-33", "ch": "ch2", "num": 33, "q": "YOU MAY CONTINUE CAREFULLY THROUGH A YELLOW LIGHT IF:", "opts": ["There is an emergency vehicle crossing your lane", "There are no pedestrians crossing", "You are turning right", "You are within the intersection"], "ans": 3, "qz": "在以下哪种情况下，你可以小心地继续通过黄灯？", "oz": ["有救护车横穿你的车道", "没有行人过马路", "你要右转", "你已经在路口内"], "story": "小狐狸已经开进路口中间了，灯变黄——这时停在路中间最危险！它就小心地开出去。还没进路口就要准备停哦。", "tip": "人已在路口内，黄灯就开出去", "tricky": true}, {"id": "ch2-34", "ch": "ch2", "num": 34, "q": "YOU MAY TURN LEFT AT A RED LIGHT IF:", "opts": ["There is no traffic coming in the opposite direction", "You are turning from a two-way street onto a one-way street", "You are turning from a one-way street onto another one-way street", "The car in front of you turns left"], "ans": 2, "qz": "在以下哪种情况下，你可以在红灯时左转？", "oz": ["对向没有来车", "从双向道转入单行道", "从单行道转入另一条单行道", "前车左转"], "story": "小兔子在单行道上，左边又是一条往左走的单行道。“单行转单行，停下看清，就能红灯左转！”双向道可不行哦。", "tip": "红灯左转：单行→单行", "tricky": true}, {"id": "ch2-35", "ch": "ch2", "num": 35, "q": "IF A TRAFFIC LIGHT IS BROKEN OR NOT FUNCTIONING YOU SHOULD:", "opts": ["Stop and wait for it to be repaired", "Stop and wait for a police officer to arrive", "Continue as if it were a four-way stop sign", "Continue as you normally would"], "ans": 2, "qz": "信号灯坏了或不工作时，你应该：", "oz": ["停下等修好", "停下等警察来", "当作四向停车标志处理", "照常行驶"], "story": "小熊来到一个灯不亮的路口，“灯睡着了！”大家都当成四面都有STOP牌：每个人先停，按先来后到轮流走。", "tip": "灯坏=四面STOP", "tricky": true}, {"id": "ch2-36", "ch": "ch2", "num": 36, "q": "YOU MAY TURN RIGHT ON RED IF YOU:", "opts": ["Stop first and check for traffic and pedestrians", "Have a right turn red arrow", "Are in the left lane", "Slow down first"], "ans": 0, "qz": "在以下哪种情况下可以红灯右转？", "oz": ["先停车并查看来车和行人", "有红色右转箭头", "你在左车道", "先减速"], "story": "小鸭子红灯想右转：先完全停下，看看左边来车、看看斑马线上的小朋友，都没有，再慢慢转。没有“禁止红灯右转”的牌子才行。", "tip": "红灯右转：先停、再看、再转", "tricky": false}, {"id": "ch2-37", "ch": "ch2", "num": 37, "q": "WHEN MAKING A RIGHT TURN ON A GREEN LIGHT, YOU MUST:", "opts": ["Maintain normal driving speed", "Stop and look for oncoming traffic", "Yield to pedestrians", "Increase your normal driving speed"], "ans": 2, "qz": "绿灯右转时，你必须：", "oz": ["保持正常车速", "停车查看对向来车", "礼让行人", "提高车速"], "story": "小猫绿灯右转，看到小鸡们正在过斑马线，“你们先走～”绿灯也要让行人。", "tip": "转弯让行人", "tricky": false}, {"id": "ch2-38", "ch": "ch2", "num": 38, "q": "THE SPEED LIMIT IS _______ MILES PER HOUR WHEN THE YELLOW LIGHTS ARE FLASHING ON THE SCHOOL ZONE SPEED SIGN.", "opts": ["25", "15", "20", "35"], "ans": 1, "qz": "学校区域限速标志的黄灯闪烁时，限速为每小时______英里。", "oz": ["25", "15", "20", "35"], "story": "小兔子开过小学门口，牌子上黄灯一闪一闪，“小朋友在这里！”只能开15英里，比自行车还慢一点点。", "tip": "学校黄灯闪=15", "tricky": true}, {"id": "ch2-39", "ch": "ch2", "num": 39, "q": "A FLASHING RED LIGHT AT A RAILROAD CROSSING MEANS:", "opts": ["Stop, do not proceed until signals are completed", "Slow down and proceed if clear", "Proceed with caution", "You have the right-of-way"], "ans": 0, "qz": "铁路道口的闪烁红灯表示：", "oz": ["停车，信号结束前不得前进", "减速，畅通就走", "小心前进", "你有优先通行权"], "story": "小乌龟看到铁轨口红灯一闪一闪叮叮叮，乖乖停住，直到灯完全不闪才走。", "tip": "铁轨闪红=停到灯停", "tricky": false}, {"id": "ch2-40", "ch": "ch2", "num": 40, "q": "THIS GREEN ARROW ON A LANE USE CONTROL SIGNAL MEANS THAT:", "opts": ["You may use this lane", "No traffic is allowed in this lane", "You have the right-of-way", "You must merge into this lane"], "ans": 0, "img": "img/ch2-40.png", "qz": "车道使用控制信号上的这个绿色箭头表示：", "oz": ["你可以使用这条车道", "此车道禁止通行", "你有优先权", "你必须并入此车道"], "story": "小熊看到车道头顶有个绿色向下箭头，“绿色就是可以用这条道！”红色X才是不许用。", "tip": "头顶绿箭头=这道能开", "tricky": false}, {"id": "ch2-41", "ch": "ch2", "num": 41, "q": "THIS SIGN MEANS:", "opts": ["Pedestrians ahead", "End of construction zone", "School crossing ahead", "Flagger ahead"], "ans": 3, "img": "img/ch2-41.png", "qz": "这个标志的意思是：", "oz": ["前方有行人", "施工区结束", "前方学校路口", "前方有旗手"], "story": "小狐狸看到橙色菱形牌子上，一个小人举着小旗子🚩。“前面有叔叔举旗指挥交通，要听他的！”", "tip": "橙牌小人举旗=旗手", "tricky": true}, {"id": "ch2-42", "ch": "ch2", "num": 42, "q": "THIS SIGN MEANS THAT:", "opts": ["A community service group is picking up trash along the highway ahead", "Workers are on or very close to the road in the work zone ahead", "Children are at play ahead", "There is a pedestrian crosswalk ahead"], "ans": 1, "img": "img/ch2-42.png", "qz": "这个标志的意思是：", "oz": ["社区团体在前方路边捡垃圾", "前方施工区有工人在路上或非常靠近道路", "前方有儿童玩耍", "前方有人行横道"], "story": "小兔子看到橙色牌子上一个小人拿铲子在挖土⛏️：“前面有工人叔叔在干活，要慢慢开！”", "tip": "橙牌挖土小人=前方有工人", "tricky": true}, {"id": "ch2-43", "ch": "ch2", "num": 43, "q": "WHEN AN ARROW PANEL IN A WORK ZONE SHOWS EITHER OF THE FOLLOWING PATTERNS, IT MEANS:", "opts": ["The bulbs on the sign are burned out", "Drive with caution", "Changes lanes immediately", "Tune your radio to a station that gives traffic updates"], "ans": 1, "img": "img/ch2-43.png", "qz": "施工区的箭头板显示以下任一图案时，表示：", "oz": ["灯泡烧坏了", "小心驾驶", "立即变道", "调收音机听路况"], "story": "小鸭子看到施工箭头板不是箭头，而是一排闪闪的灯或四角的灯，“这不是让我变道，是说：小心开哦！”", "tip": "箭头板没箭头只闪灯=小心", "tricky": true}, {"id": "ch2-44", "ch": "ch2", "num": 44, "q": "THE CENTER LANE IN THE ILLUSTRATION IS USED FOR:", "opts": ["Regular travel", "Left turns only", "Passing only", "Emergency vehicles only"], "ans": 1, "img": "img/ch2-44.png", "qz": "图中的中央车道用于：", "oz": ["正常行驶", "仅限左转", "仅限超车", "仅限紧急车辆"], "story": "小猪看到马路中间那条两边都画着黄线、里面有左转箭头的车道，“这是左转专用小格子，两个方向的车都能在这里等着左转！”不能在这里一直开或超车。", "tip": "中间双向左转道=只用来左转", "tricky": true}, {"id": "ch2-45", "ch": "ch2", "num": 45, "q": "YOU MAY PASS IF THE LINE DIVIDING TWO LANES IS A ___________ LINE.", "opts": ["Broken white", "Double solid yellow", "Solid yellow", "Solid white"], "ans": 0, "qz": "如果分隔两条车道的是________线，你可以超车。", "oz": ["白色虚线", "双黄实线", "黄实线", "白实线"], "story": "小兔子说：虚线像小门开着，可以过去；实线像墙，不要过。同方向白色虚线，看清了就能超车。", "tip": "虚线可过，实线别过", "tricky": false}, {"id": "ch2-46", "ch": "ch2", "num": 46, "q": "LANES OF TRAFFIC MOVING IN THE SAME DIRECTION ARE DIVIDED BY ____ LINES.", "opts": ["Yellow", "White", "Red", "Black"], "ans": 1, "qz": "同方向行驶的车道用____线分隔。", "oz": ["黄", "白", "红", "黑"], "story": "小熊记颜色：白色是“好朋友同方向”，黄色是“对面来车要小心”。", "tip": "同向白，对向黄", "tricky": true}, {"id": "ch2-47", "ch": "ch2", "num": 47, "q": "YOU MAY NOT PASS ANOTHER CAR ON EITHER SIDE OF A _______ CENTERLINE.", "opts": ["Combination solid and broken yellow", "Single broken yellow", "Double solid yellow", "Single broken white"], "ans": 2, "qz": "在________中心线的任何一侧都不能超车。", "oz": ["实线与虚线组合的黄线", "单条黄虚线", "双黄实线", "单条白虚线"], "story": "小狐狸看到马路中间两条黄黄的实线，“两堵墙！”两边的车都不能越过去超车。", "tip": "双黄实线=两边都不许超", "tricky": false}, {"id": "ch2-48", "ch": "ch2", "num": 48, "q": "YOU MAY CROSS SOLID YELLOW LINES:", "opts": ["To pass traffic moving in the same direction", "During daylight hours only", "At any time", "When making turns"], "ans": 3, "qz": "你可以越过黄色实线：", "oz": ["超越同方向的车", "仅限白天", "任何时候", "转弯时"], "story": "小猫要左转进一个小区，需要穿过黄实线——“转弯可以过，超车不行哦！”", "tip": "黄实线：转弯可越，超车不行", "tricky": true}, {"id": "ch2-49", "ch": "ch2", "num": 49, "q": "THE ROAD EDGE ON THE RIGHT SIDE IS MARKED BY A ___________ LINE.", "opts": ["Broken white", "Solid yellow", "Solid white", "Broken yellow audio"], "ans": 2, "qz": "道路右侧边缘用________线标出。", "oz": ["白色虚线", "黄色实线", "白色实线", "黄色虚线"], "story": "小鸭子沿着路边那条白白的实线开，“这是路的右边边，再过去就是路肩啦。”左边边是黄的哦。", "tip": "右边白实线，左边黄", "tricky": true}, {"id": "ch2-50", "ch": "ch2", "num": 50, "q": "LANES OF TRAFFIC MOVING IN THE OPPOSITE DIRECTION ARE DIVIDED BY ____ LINES.", "opts": ["White", "Red", "Black", "Yellow"], "ans": 3, "qz": "相反方向行驶的车道用____线分隔。", "oz": ["白", "红", "黑", "黄"], "story": "小兔子看到中间黄线：“黄线那边的车是迎面来的！”", "tip": "对向黄线", "tricky": false}, {"id": "ch2-51", "ch": "ch2", "num": 51, "q": "WHEN YOU SEE THIS BLACK AND YELLOW SIGN, IT MEANS:", "opts": ["The road to the right is for one-way traffic only", "Detour to the right because of road construction", "Slow down because the road ahead changes direction at an extreme angle", "There is a cross road ahead on your right"], "ans": 2, "img": "img/ch2-51.png", "qz": "看到这个黑黄标志，意思是：", "oz": ["右边是单行道", "因施工向右绕行", "减速，前方道路急转弯", "右侧前方有交叉路口"], "story": "小乌龟看到路尽头立着一块横长的黄牌子，上面一个超大粗箭头指向右边：“路到这里要猛地改方向啦！”提前减速才不会冲出去。", "tip": "横长大箭头=路急转方向", "tricky": true}, {"id": "ch2-52", "ch": "ch2", "num": 52, "q": "WHEN YOU SEE THIS SIGN, IT MEANS:", "opts": ["There is an object on the roadway", "Traffic is coming from the right", "The road is curving sharply to the left", "There is a merge point ahead"], "ans": 2, "img": "img/ch2-52.png", "qz": "看到这个标志，意思是：", "oz": ["路上有障碍物", "右侧有来车", "道路向左急弯", "前方有并道点"], "story": "小熊看到黄牌子上一个大大的“<”尖角（V形箭头）指向左边，“路要猛地往左拐啦！”", "tip": "V尖角指哪=往哪急拐", "tricky": true}, {"id": "ch2-53", "ch": "ch2", "num": 53, "q": "AT AN INTERSECTION CONTROLLED BY A STOP SIGN, IF YOU CAN’T GET A GOOD VIEW OF CROSS-STREET TRAFFIC WHEN YOU STOP BEHIND THE WHITE TOP BAR PAINTED ON THE PAVEMENT, YOU SHOULD:", "opts": ["Wait 5 seconds, then proceed.", "Sound your horn before proceeding", "Put down your windows, listen for traffic, and then proceed", "Pull forward slowly, check for traffic and pedestrians, and proceed when clear"], "ans": 3, "qz": "在停车标志控制的路口，如果你停在白色停车线后看不清横向来车，你应该：", "oz": ["等5秒再走", "按喇叭后再走", "摇下车窗听声音再走", "慢慢往前开，查看车辆和行人，畅通再走"], "story": "小兔子停在白线后，被大树挡住看不见。她先停好，再一点一点往前“探探头”，看清没车没人才走。", "tip": "看不清就慢慢探头", "tricky": true}, {"id": "ch2-54", "ch": "ch2", "num": 54, "q": "THE POSTED SPEED LIMITS SHOW:", "opts": ["The minimum legal speed limit", "The exact speed at which you must travel to avoid a ticket", "The maximum safe speed under ideal road and weather conditions", "The maximum safe speed under all road conditions"], "ans": 2, "qz": "标示的限速表示：", "oz": ["最低法定速度", "必须精确遵守以免罚单的速度", "理想路况和天气下的最高安全速度", "任何路况下的最高安全速度"], "story": "小猪看到限速55，“这是天气好、路好时最快的速度！”下雨下雪还要更慢。", "tip": "限速=好天气的最高速", "tricky": true}, {"id": "ch2-55", "ch": "ch2", "num": 55, "q": "A HIGHWAY WITH TWO-WAY TRAFFIC IS MARKED BY WHICH OF THESE SIGNS?", "opts": ["1", "2", "3", "4"], "ans": 2, "img": "img/ch2-55.png", "qz": "哪个标志表示双向通行的公路？", "oz": ["1", "2", "3", "4"], "story": "小狐狸看到3号牌子上一个箭头朝上、一个朝下，“一上一下=两边都有车来回走！”", "tip": "一上一下箭头=双向", "tricky": true}, {"id": "ch2-56", "ch": "ch2", "num": 56, "q": "FROM THE CENTER LANE, WHAT MANEUVERS CAN YOU PERFORM?", "opts": ["Make left turns", "Make U-turns", "Pass slower-moving traffic", "All of the above"], "ans": 0, "qz": "在中央车道你可以做什么？", "oz": ["左转", "掉头", "超越慢车", "以上都是"], "story": "小鸭子在中间那条左转车道上，只做一件事：左转！不能在里面超车，也不在这里开着跑。", "tip": "中间道只左转", "tricky": true}, {"id": "ch2-57", "ch": "ch2", "num": 57, "q": "WHICH OF THESE SIGNS MEANS THAT DRIVERS SHOULD KEEP TO THE RIGHT?", "opts": ["2", "1", "3", "4"], "ans": 0, "img": "img/ch2-57.png", "qz": "哪个标志表示司机应靠右行驶？", "oz": ["2", "1", "3", "4"], "story": "小兔子看到2号白牌子，箭头绕过一个小岛往右边走，“前面有障碍，从右边走！”注意选A才是2号哦。", "tip": "箭头绕障碍往右=靠右", "tricky": true}, {"id": "ch3-1", "ch": "ch3", "num": 1, "q": "TEENAGE DRIVERS ARE MORE LIKELY TO BE INVOLVED IN A CRASH WHEN:", "opts": ["They are driving with their pet as a passenger", "They are driving with adult passengers", "They are driving with teenage passengers", "They are driving without any passengers"], "ans": 2, "qz": "青少年司机在什么情况下更容易出车祸？", "oz": ["车上载着宠物", "载着成年乘客", "载着青少年乘客", "没有乘客"], "story": "小兔子刚学会开车，后座坐满了蹦蹦跳跳的小兔朋友，叽叽喳喳好热闹，小兔子一回头聊天——差点撞树！同龄朋友越多越容易分心。", "tip": "新手别载一车小伙伴", "tricky": true}, {"id": "ch3-2", "ch": "ch3", "num": 2, "q": "DRIVERS WHO EAT AND DRINK WHILE DRIVING:", "opts": ["Have no driving errors", "Have trouble driving slow", "Are better drivers because they are not hungry", "Have trouble controlling their vehicles"], "ans": 3, "qz": "开车时吃东西喝饮料的司机：", "oz": ["不会有驾驶失误", "很难开慢", "因为不饿开得更好", "难以控制车辆"], "story": "小猪一手汉堡一手奶茶，方向盘没人管，车子歪歪扭扭。“吃完再开！”", "tip": "手里有吃的=车没人管", "tricky": false}, {"id": "ch3-3", "ch": "ch3", "num": 3, "q": "PREPARING TO SMOKE AND SMOKING WHILE DRIVING:", "opts": ["Do not affect driving abilities", "Help maintain driver alertness", "Are distracting activities", "Are not distracting activities"], "ans": 2, "qz": "开车时准备抽烟和抽烟：", "oz": ["不影响驾驶能力", "帮助保持清醒", "属于分心行为", "不属于分心行为"], "story": "小狐狸找打火机、点烟、弹烟灰，眼睛和手都离开了驾驶。这些都是“分心”。", "tip": "找东西点东西=分心", "tricky": false}, {"id": "ch3-4", "ch": "ch3", "num": 4, "q": "THE TOP MAJOR CRASH TYPE FOR 16 YEAR OLD DRIVERS IN PENNSYLVANIA IS:", "opts": ["Single vehicle/run-off-the-road", "Being sideswiped on an interstate", "Driving in reverse on a side street", "Driving on the shoulder of a highway"], "ans": 0, "qz": "宾州16岁司机最主要的事故类型是：", "oz": ["单车/冲出道路", "在州际公路被侧刮", "在小路倒车", "在高速路肩行驶"], "story": "小鸭子刚16岁，弯道开太快、一分神，没撞别人，自己冲出了马路掉进草地。新手最常见就是“自己冲出去”。", "tip": "16岁最常见：自己冲出路", "tricky": true}, {"id": "ch3-5", "ch": "ch3", "num": 5, "q": "WHEN PASSING A BICYCLIST, YOU SHOULD:", "opts": ["Blast your horn to alert the bicyclist", "Move as far left as possible", "Remain in the center of the lane", "Put on your four-way flashers"], "ans": 1, "qz": "超越骑自行车的人时，你应该：", "oz": ["猛按喇叭提醒", "尽量靠左", "保持在车道中间", "打开双闪"], "story": "小熊开车遇到骑车的小松鼠，轻轻往左边让出大大的空间（至少4英尺），不按喇叭吓它。", "tip": "超自行车：往左让出大空间", "tricky": true}, {"id": "ch3-6", "ch": "ch3", "num": 6, "q": "WHEN YOU DRIVE THROUGH AN AREA WHERE CHILDREN ARE PLAYING, YOU SHOULD EXPECT THEM:", "opts": ["To know when it is safe to cross", "To stop at the curb before crossing the street", "To run out in front of you without looking", "Not to cross unless they are with an adult"], "ans": 2, "qz": "开车经过有儿童玩耍的区域时，你应该预料到他们：", "oz": ["知道何时安全过马路", "过马路前会在路边停下", "会不看路突然冲到你车前", "不和大人一起就不过马路"], "story": "小朋友追皮球⚽可不会看车！小兔子开过公园，脚放在刹车上，随时准备停。", "tip": "有小孩=随时会冲出来", "tricky": false}, {"id": "ch3-7", "ch": "ch3", "num": 7, "q": "IF YOU ARE DRIVING BEHIND A MOTORCYCLE, YOU MUST:", "opts": ["Allow the motorcycle to use a complete lane", "Drive on the shoulder beside the motorcycle", "Allow the motorcycle to use only half a lane", "Pass in the same lane where the motorcycle is driving"], "ans": 0, "qz": "如果你跟在摩托车后面，你必须：", "oz": ["让摩托车使用整条车道", "开到路肩和它并排", "只让它用半条车道", "在它同一车道超车"], "story": "小猫骑摩托也是正经车辆哦！它要占一整条车道，不能挤着它并排开。", "tip": "摩托车=一整条道", "tricky": true}, {"id": "ch3-8", "ch": "ch3", "num": 8, "q": "WHEN TRAVELING BEHIND A MOTORCYCLE:", "opts": ["Allow a following distance of at least 2 car lengths", "Allow at least 2 seconds of following distance", "Allow at least 4 seconds of following distance", "Allow a following distance of at least 4 motorcycle lengths"], "ans": 2, "qz": "跟在摩托车后面时：", "oz": ["至少保持2个车身距离", "至少保持2秒跟车距离", "至少保持4秒跟车距离", "至少保持4个摩托车身距离"], "story": "摩托车刹车很快，小熊跟在后面数“一只兔、两只兔、三只兔、四只兔”，至少4秒才安全。", "tip": "跟摩托：4秒", "tricky": true}, {"id": "ch3-9", "ch": "ch3", "num": 9, "q": "YOU NEED TO USE EXTRA CAUTION WHEN DRIVING NEAR A PEDESTRIAN USING A WHITE CANE BECAUSE:", "opts": ["He or she is deaf", "He or she has a mental disability", "He or she is blind", "He or she has a walking problem"], "ans": 2, "qz": "在使用白手杖的行人附近开车要格外小心，因为：", "oz": ["他/她是聋人", "他/她有智力障碍", "他/她是盲人", "他/她行走不便"], "story": "白手杖是看不见的人的小眼睛👀。小兔子替他看路，慢慢让他先过。", "tip": "白手杖=盲人", "tricky": false}, {"id": "ch3-10", "ch": "ch3", "num": 10, "q": "WHEN DRIVING NEAR A BLIND PEDESTRIAN WHO IS CARRYING A WHITE CANE OR USING A GUIDE DOG, YOU SHOULD:", "opts": ["Slow down and be prepared to stop", "Take the right-of-way", "Proceed normally", "Drive away quickly"], "ans": 0, "qz": "在拿白手杖或带导盲犬的盲人附近开车时，你应该：", "oz": ["减速并准备停车", "抢先通行", "正常行驶", "快速开走"], "story": "导盲犬汪汪带着主人过马路，小熊停下来乖乖等，不抢不催。", "tip": "白手杖导盲犬：慢、准备停", "tricky": false}, {"id": "ch3-11", "ch": "ch3", "num": 11, "q": "WHO MUST YIELD WHEN A DRIVER IS TURNING AND A PEDESTRIAN IS CROSSING WITHOUT", "opts": ["TRAFFIC LIGHT?", "The driver", "Whoever is slower", "The pedestrian"], "ans": 1, "qz": "没有信号灯时，司机转弯而行人正在过马路，谁必须让行？", "oz": ["谁后开始谁让", "司机", "谁慢谁让", "行人"], "story": "小猫转弯时看到小鸡在过马路，“车让人！”车子又大又硬，小鸡小小软软，当然车要让。", "tip": "转弯遇行人：车让人", "tricky": false}, {"id": "ch3-12", "ch": "ch3", "num": 12, "q": "AN ORANGE TRIANGLE ON THE BACK OF A VEHICLE INDICATES THAT VEHICLE:", "opts": ["Carries radioactive materials", "Takes wide turns", "Travels at slower speeds than normal traffic", "Makes frequent stops"], "ans": 2, "qz": "车辆后面的橙色三角形表示该车：", "oz": ["载有放射性物质", "转弯很宽", "比正常车流速度慢", "经常停车"], "story": "小乌龟拖拉机后面挂着橙色三角牌：“我开得很慢哦～”看到它要提早减速。", "tip": "橙三角=慢车", "tricky": true}, {"id": "ch3-13", "ch": "ch3", "num": 13, "q": "AT NIGHT, IT IS HARDEST TO SEE:", "opts": ["Road signs", "Pedestrians", "Other motorists", "Street lights"], "ans": 1, "qz": "夜间最难看清的是：", "oz": ["路标", "行人", "其他车辆", "路灯"], "story": "晚上路标会反光、车有大灯，可是穿深色衣服的小兔子行人什么都不亮，最难看见！", "tip": "夜里最难看见行人", "tricky": false}, {"id": "ch3-14", "ch": "ch3", "num": 14, "q": "WHEN A TRUCK DRIVER BEHIND YOU WANTS TO PASS YOUR VEHICLE, YOUR SPEED SHOULD:", "opts": ["Remain steady or decrease", "Change lanes", "Change", "Increase"], "ans": 0, "qz": "卡车司机想超你的车时，你的速度应该：", "oz": ["保持不变或降低", "变道", "改变", "提高"], "story": "大象卡车要超小兔子，小兔子不加速，稳稳地或者稍微慢一点，让大象快点过去。", "tip": "被超车：别加速", "tricky": false}, {"id": "ch3-15", "ch": "ch3", "num": 15, "q": "WHEN SHARING THE ROAD WITH A TRUCK, IT IS IMPORTANT TO REMEMBER THAT, IN GENERAL, TRUCKS:", "opts": ["Take longer distances than cars to stop", "Require less time to pass on a downgrade than cars", "Require less turning radius than cars", "Require less time to pass on an incline than cars"], "ans": 0, "qz": "和卡车共用道路时要记住，一般来说卡车：", "oz": ["比小汽车需要更长的刹车距离", "下坡超车比汽车用时少", "转弯半径比汽车小", "上坡超车比汽车用时少"], "story": "大象卡车好重好重，踩刹车要滑好远才停下。所以别突然切到它前面。", "tip": "卡车重=停得慢", "tricky": false}, {"id": "ch3-16", "ch": "ch3", "num": 16, "q": "IF YOU STOP AT A RAILROAD CROSSING WITH MORE THAN ONE TRACK:", "opts": ["Wait until you have a clear view of both tracks", "Stop on the railroad track and watch for another train", "Go through as soon as the train passes", "Go through when one of the tracks is free"], "ans": 0, "qz": "如果你停在有多条轨道的铁路道口：", "oz": ["等到能清楚看到所有轨道", "停在轨道上看另一列火车", "火车一过就走", "有一条轨道空了就走"], "story": "一列火车过去了，小狐狸先别动——后面另一条轨道可能藏着第二列火车🚂！两条都看清了才走。", "tip": "多条轨道：全部看清再走", "tricky": true}, {"id": "ch3-17", "ch": "ch3", "num": 17, "q": "IF YOU ARE FOLLOWING A TRUCK THAT SWINGS LEFT BEFORE MAKING A RIGHT TURN AT AN INTERSECTION, YOU SHOULD REMEMBER THAT IT IS VERY DANGEROUS TO:", "opts": ["Try to squeeze between the truck and curb to make a right turn", "Apply your brakes until the truck has completed the turn", "Violate the “4 – second” following distance rule", "Honk your horn at the truck driver"], "ans": 0, "qz": "如果跟着一辆右转前先往左甩的卡车，非常危险的是：", "oz": ["想从卡车和路边之间挤进去右转", "刹车直到卡车转完", "违反4秒跟车规则", "对卡车司机按喇叭"], "story": "大象卡车右转要先往左边甩一下，右边空出一条缝。小兔子千万别钻进去，大象一转就把缝挤没了！", "tip": "卡车右转，右边的缝别钻", "tricky": true}, {"id": "ch3-18", "ch": "ch3", "num": 18, "q": "THE ONLY TIME YOU DO NOT HAVE TO STOP FOR A SCHOOL BUS WHOSE RED LIGHTS ARE FLASHING AND STOP ARM IS EXTENDED IS WHEN YOU:", "opts": ["Are driving on the opposite side of a divided highway", "Are behind the bus", "See no children present", "Can safely pass on the left"], "ans": 0, "qz": "校车红灯闪烁、停车臂伸出时，唯一不必停车的情况是：", "oz": ["你在分隔公路（有隔离带）的对面", "你在校车后面", "没看到孩子", "可以从左边安全超过"], "story": "小熊在有隔离带的大马路另一边，校车在对面停着，中间隔着草坪隔离带，小朋友不会走过来，所以不用停。其他情况都要停！", "tip": "只有隔离带对面不用停", "tricky": true}, {"id": "ch3-19", "ch": "ch3", "num": 19, "q": "WHEN A SCHOOL BUS HAS ITS LIGHTS FLASHING AND ITS STOP ARM EXTENDED, YOU MUST:", "opts": ["Stop at least 10 feet away from the bus", "Pass if children have exited the bus", "Stop if the bus is on the opposite side of a barrier", "Drive slowly by the bus"], "ans": 0, "qz": "校车闪灯并伸出停车臂时，你必须：", "oz": ["在离校车至少10英尺处停车", "孩子下车后就可以超过", "校车在隔离物对面时也停车", "慢慢从旁边开过"], "story": "黄色校车伸出红色STOP小手，小兔子停在至少10英尺（大约两只长颈鹿躺下）外面。", "tip": "校车停：至少10英尺外停", "tricky": true}, {"id": "ch3-20", "ch": "ch3", "num": 20, "q": "AFTER A TRAIN HAS PASSED, YOU SHOULD:", "opts": ["Check again for approaching trains and proceed with caution", "Wait for a green light", "Proceed across the tracks", "Blow horn and proceed"], "ans": 0, "qz": "火车过去之后，你应该：", "oz": ["再次查看是否有火车，然后小心前进", "等绿灯", "直接过铁轨", "按喇叭然后走"], "story": "火车呜呜开走了，小鸭子再左右看一眼，确认没有第二列，才慢慢过去。", "tip": "火车过后再看一次", "tricky": false}, {"id": "ch3-21", "ch": "ch3", "num": 21, "q": "IF YOU NEED TO SLOW DOWN OR STOP WHEN OTHER DRIVERS MAY NOT EXPECT IT, YOU SHOULD:", "opts": ["Quickly tap your brake pedal a few times", "Use your emergency brake", "Look over your shoulder for traffic in your blind spot", "Get ready to blow your horn"], "ans": 0, "qz": "如果你需要在别人可能没想到的地方减速或停车，你应该：", "oz": ["快速轻踩刹车几下", "使用紧急手刹", "回头看盲区", "准备按喇叭"], "story": "小猫要突然在小巷口停车，轻轻点点点刹车，让刹车灯一闪一闪：“后面的朋友，我要慢下来啦！”", "tip": "意外减速：点几下刹车", "tricky": true}, {"id": "ch3-22", "ch": "ch3", "num": 22, "q": "WHEN YOU ARE PLANNING TO MAKE A TURN, YOU SHOULD ACTIVATE YOUR TURN SIGNALS:", "opts": ["Only if there are other drivers following you", "Just as the front of your car reaches the intersection", "3 to 4 seconds before you reach the intersection", "2 car lengths before reaching the intersection"], "ans": 2, "qz": "准备转弯时，你应该在什么时候打转向灯？", "oz": ["只在后面有车时", "车头到路口时", "到达路口前3到4秒", "到路口前2个车身"], "story": "小兔子数“一二三四”，在到路口前3到4秒就打灯，让大家早早知道她要转。", "tip": "转弯前3-4秒打灯", "tricky": true}, {"id": "ch3-23", "ch": "ch3", "num": 23, "q": "BEFORE PASSING ANOTHER VEHICLE YOU SHOULD:", "opts": ["Flash your headlights to alert the driver", "Turn on your four-way flashers to warn the driver", "Give the proper turn signal to show you are changing lanes", "Sound your horn to get the drivers attention"], "ans": 2, "qz": "超车前你应该：", "oz": ["闪大灯提醒司机", "打开双闪警告司机", "打正确的转向灯表示要变道", "按喇叭吸引司机注意"], "story": "小熊要超车，先打转向灯，“我要换道啦！”不是闪灯也不是按喇叭。", "tip": "超车先打灯", "tricky": false}, {"id": "ch3-24", "ch": "ch3", "num": 24, "q": "YOUR BLIND SPOT IS THE AREA OF THE ROAD:", "opts": ["You cannot see without moving your head", "Directly behind your vehicle", "You see in your rearview mirror", "You see in your side mirror"], "ans": 0, "qz": "你的盲区是道路上：", "oz": ["你不转头就看不到的区域", "车辆正后方", "后视镜里看到的区域", "侧视镜里看到的区域"], "story": "小猫照镜子看不到身边一小块地方，那里藏着小摩托！要扭扭头才能看到——这就是盲区。", "tip": "盲区=不转头看不到", "tricky": false}, {"id": "ch3-25", "ch": "ch3", "num": 25, "q": "BEFORE PASSING ANOTHER VEHICLE, YOU SHOULD SIGNAL:", "opts": ["Just before changing lanes", "At any time", "After changing lanes", "Early enough so others know your plans"], "ans": 3, "qz": "超车前，你应该打转向灯：", "oz": ["在变道前一刻", "任何时候", "变道后", "足够早，让别人知道你的计划"], "story": "小兔子说：打灯就像提前说“我要过去喽”，要早一点说，大家才来得及准备。", "tip": "灯要早打", "tricky": true}, {"id": "ch3-26", "ch": "ch3", "num": 26, "q": "BEFORE CHANGING LANES ON A MULTI-LANE HIGHWAY YOU SHOULD:", "opts": ["Sound your horn", "Turn on your headlights", "Reduce your speed", "Check your mirrors and blind spots"], "ans": 3, "qz": "在多车道公路上变道前，你应该：", "oz": ["按喇叭", "开大灯", "降低车速", "查看后视镜和盲区"], "story": "小狐狸变道前：看看镜子，再扭头看看盲区，没有小伙伴才换。", "tip": "变道：镜子+扭头", "tricky": false}, {"id": "ch3-27", "ch": "ch3", "num": 27, "q": "WHEN YOU PARK ON THE ROADWAY, YOU SHOULD:", "opts": ["Use your four-way flashers", "Park at an angle", "Keep your turn signal on", "Turn your lights on"], "ans": 0, "qz": "在路上停车时，你应该：", "oz": ["打开双闪", "斜着停", "一直开着转向灯", "打开车灯"], "story": "小猪车停在路边，打开双闪一闪一闪：“我停在这里哦，小心！”", "tip": "路边停车：双闪", "tricky": true}, {"id": "ch3-28", "ch": "ch3", "num": 28, "q": "BEFORE BACKING UP, YOU SHOULD:", "opts": ["Rely on your mirrors to see if it is clear to proceed", "Flash your lights", "Open your door to see if it is clear to proceed", "Turn your head and look through the rear window"], "ans": 3, "qz": "倒车前，你应该：", "oz": ["依靠后视镜看是否安全", "闪车灯", "打开车门看看", "转头从后窗看"], "story": "小鸭子倒车，扭过头从后窗看，车后可能有小小的猫咪，镜子不一定看得到。", "tip": "倒车要扭头看后窗", "tricky": true}, {"id": "ch3-29", "ch": "ch3", "num": 29, "q": "TO HELP AVOID CRASHES, YOU SHOULD:", "opts": ["Communicate with other drivers on the road", "Ignore other drivers on the road", "Drive on side streets and back roads", "Avoid driving during rush hour"], "ans": 0, "qz": "为了避免车祸，你应该：", "oz": ["和路上其他司机沟通", "无视其他司机", "走小路", "避开高峰时段"], "story": "小兔子用转向灯、刹车灯、喇叭和眼神跟别人“说话”，大家都知道彼此要干嘛，就不会撞。", "tip": "开车要“说话”：灯和信号", "tricky": false}, {"id": "ch3-30", "ch": "ch3", "num": 30, "q": "THE DRIVER IS:", "opts": ["Slowing or stopping", "Turning left", "Turning right", "Opening his/her door"], "ans": 0, "img": "img/ch3-30.png", "qz": "这位司机正在：", "oz": ["减速或停车", "左转", "右转", "打开车门"], "story": "小熊伸出左手，手臂往下垂，像在说“慢一点、要停啦”。手往下=减速停车。", "tip": "手臂向下=减速/停", "tricky": true}, {"id": "ch3-31", "ch": "ch3", "num": 31, "q": "IF YOUR TURN SIGNALS FAIL, YOU SHOULD USE _____ TO INDICATE YOU ARE TURNING.", "opts": ["Your horn", "Your headlights", "Hand signals", "Your emergency flashers"], "ans": 2, "qz": "如果转向灯坏了，你应该用_____表示转弯。", "oz": ["喇叭", "大灯", "手势", "双闪"], "story": "小猫的转向灯坏了，就伸出小爪子打手势：手平伸=左转，手向上=右转，手向下=停。", "tip": "灯坏用手势", "tricky": false}, {"id": "ch3-32", "ch": "ch3", "num": 32, "q": "WHEN TRAVELING BELOW 40 MILES PER HOUR ON A LIMITED ACCESS HIGHWAY, YOU SHOULD:", "opts": ["Drive on the shoulder", "Use your high beams", "Sound your horn to warn others", "Use your four-way flashers"], "ans": 3, "qz": "在限制出入的高速公路上低于每小时40英里行驶时，你应该：", "oz": ["开到路肩", "开远光灯", "按喇叭警告别人", "打开双闪"], "story": "小乌龟在高速上只能开很慢，打开双闪：“我很慢哦，大家小心！”", "tip": "高速太慢开双闪", "tricky": true}, {"id": "ch3-33", "ch": "ch3", "num": 33, "q": "YOU SHOULD HONK YOUR HORN WHEN YOU:", "opts": ["Are travelling through an intersection", "Are passing a bicyclist", "See a child who is about to run into the street", "Are parallel parking"], "ans": 2, "qz": "什么时候你应该按喇叭？", "oz": ["经过路口时", "超自行车时", "看到小孩快要冲到马路上", "侧方停车时"], "story": "小兔子看到小朋友追球要冲出来，“嘀！”轻轻按喇叭提醒他。喇叭是用来防危险的，不是吓人的。", "tip": "喇叭=提醒危险", "tricky": false}, {"id": "ch3-34", "ch": "ch3", "num": 34, "q": "YOU MUST USE YOUR HEADLIGHTS WHEN OTHER VEHICLES ARE NOT VISIBLE FROM _____ FEET AWAY.", "opts": ["1000", "1500", "1800", "1200"], "ans": 0, "qz": "当你看不清_____英尺外的其他车辆时，必须开大灯。", "oz": ["1000", "1500", "1800", "1200"], "story": "下雾了，小熊看不到1000英尺（大约3个足球场）外的车，就打开大灯。", "tip": "看不清1000尺就开灯", "tricky": true}, {"id": "ch3-35", "ch": "ch3", "num": 35, "q": "IF A VEHICLE USING HIGH BEAMS COMES TOWARD YOU, YOU SHOULD:", "opts": ["Turn on your high beams", "Turn off your headlights", "Sound your horn", "Flash your high beams"], "ans": 3, "qz": "如果对面来车开着远光灯，你应该：", "oz": ["打开你的远光灯", "关掉车灯", "按喇叭", "闪一下远光灯"], "story": "对面大灯照得小猫眼睛花花，它闪一下远光灯提醒：“朋友，关一下远光吧～”然后自己不要一直开远光报复哦。", "tip": "对面远光：闪一下提醒", "tricky": true}, {"id": "ch3-36", "ch": "ch3", "num": 36, "q": "IF A VEHICLE USING HIGH BEAMS COMES TOWARD YOU, YOU SHOULD LOOK TOWARDS _____ OF THE ROAD.", "opts": ["Either side", "The center", "The right side", "The left side"], "ans": 2, "qz": "对面来车开远光灯时，你应该看向道路的_____。", "oz": ["任意一侧", "中间", "右侧", "左侧"], "story": "小兔子被大灯晃眼，眼睛往右边路边的白线看，沿着白线开，就不会被晃瞎。", "tip": "被晃眼看右边白线", "tricky": true}, {"id": "ch3-37", "ch": "ch3", "num": 37, "q": "YOU MAY HONK YOUR HORN WHEN YOU:", "opts": ["Have to stop quickly", "Are passing another car", "Have lost control of your car", "Are passing a bicyclist"], "ans": 2, "qz": "什么时候你可以按喇叭？", "oz": ["需要急停时", "超车时", "车子失控时", "超自行车时"], "story": "小猪的车子失控打滑了，“嘀嘀嘀！”赶快按喇叭警告周围的人快躲开。", "tip": "失控了按喇叭", "tricky": true}, {"id": "ch3-38", "ch": "ch3", "num": 38, "q": "YOUR BRAKE LIGHTS TELL OTHER DRIVERS THAT YOU:", "opts": ["Are making a turn", "Have your emergency brake on", "Are changing lanes", "Are slowing down or stopping"], "ans": 3, "qz": "你的刹车灯告诉其他司机你：", "oz": ["要转弯", "拉着手刹", "要变道", "在减速或停车"], "story": "小狐狸一踩刹车，屁股后面红灯亮亮，后面的朋友就知道“它要慢下来啦”。", "tip": "刹车灯=减速/停车", "tricky": false}, {"id": "ch3-39", "ch": "ch3", "num": 39, "q": "BEFORE TURNING, YOU SHOULD:", "opts": ["Use your signal", "Turn the wheel", "Increase your speed", "Change lanes"], "ans": 0, "qz": "转弯前，你应该：", "oz": ["打转向灯", "转方向盘", "加速", "变道"], "story": "小鸭子转弯前第一件事：滴答滴答打灯！", "tip": "转弯先打灯", "tricky": false}, {"id": "ch3-40", "ch": "ch3", "num": 40, "q": "THE DRIVER IS:", "opts": ["Turning left", "Slowing", "Stopping", "Turning right"], "ans": 3, "img": "img/ch3-40.png", "qz": "这位司机正在：", "oz": ["左转", "减速", "停车", "右转"], "story": "小熊伸出左手，手肘弯起来手往上举，像举手回答问题🙋——那就是要右转！", "tip": "手往上=右转", "tricky": true}, {"id": "ch3-41", "ch": "ch3", "num": 41, "q": "THE DRIVER IS:", "opts": ["Turning left", "Stopping", "Slowing", "Turning right"], "ans": 0, "img": "img/ch3-41.png", "qz": "这位司机正在：", "oz": ["左转", "停车", "减速", "右转"], "story": "小兔子伸出左手直直平平地指向左边：“我要往这边走！”平伸=左转。", "tip": "手平伸=左转", "tricky": true}, {"id": "ch3-42", "ch": "ch3", "num": 42, "q": "IF ANOTHER CAR IS IN DANGER OF HITTING YOU, YOU SHOULD:", "opts": ["Sound your horn", "Wave your arms", "Use your emergency lights", "Flash your headlights"], "ans": 0, "qz": "如果另一辆车有撞到你的危险，你应该：", "oz": ["按喇叭", "挥手臂", "开紧急灯", "闪大灯"], "story": "小猫看到一辆车歪歪地快撞过来，赶紧“嘀——”按喇叭，声音最快能提醒对方。", "tip": "快被撞：按喇叭", "tricky": false}, {"id": "ch3-43", "ch": "ch3", "num": 43, "q": "IF YOU BEGIN TO FEEL TIRED WHILE DRIVING, THE BEST THING TO DO IS:", "opts": ["Get some coffee", "Open your window", "Stop driving", "Turn on the radio"], "ans": 2, "qz": "开车时开始觉得累，最好的做法是：", "oz": ["喝咖啡", "开窗", "停止驾驶", "开收音机"], "story": "小熊打哈欠了，咖啡和开窗只能骗自己一小会儿。最好是停下来睡一觉😴。", "tip": "困了就停车", "tricky": true}, {"id": "ch3-44", "ch": "ch3", "num": 44, "q": "THE EFFECT THAT LACK OF SLEEP HAS ON YOUR SAFE DRIVING ABILITY IS THE SAME AS:", "opts": ["The effect that alcohol has", "The effect that amphetamines have", "The effect that anger has", "The effect that driving with teenagers has"], "ans": 0, "qz": "缺乏睡眠对安全驾驶能力的影响与什么相同？", "oz": ["酒精的影响", "安非他命的影响", "愤怒的影响", "和青少年一起开车的影响"], "story": "小狐狸一夜没睡，开车反应慢吞吞，就像喝醉了一样！", "tip": "没睡觉=像喝醉", "tricky": true}, {"id": "ch3-45", "ch": "ch3", "num": 45, "q": "TEENAGERS SHOULD TRY TO GET AT LEAST ___ OF SLEEP EACH NIGHT TO AVOID THE RISK OF DROWSY DRIVING CRASHES.", "opts": ["7 hours", "6 hours", "8 hours", "9 hours"], "ans": 2, "qz": "青少年每晚至少应睡___，以避免疲劳驾驶事故。", "oz": ["7小时", "6小时", "8小时", "9小时"], "story": "小兔子每天睡够8小时，第二天精神满满开小车。", "tip": "青少年睡8小时", "tricky": true}, {"id": "ch3-46", "ch": "ch3", "num": 46, "q": "IF ANOTHER DRIVER CUTS YOU OFF IN TRAFFIC, YOU SHOULD:", "opts": ["Pull next to the driver and yell at him or her", "Ignore the other driver", "Flash your high beams at the driver", "Get back at the other driver by cutting him or her off"], "ans": 1, "qz": "如果另一位司机在车流中加塞到你前面，你应该：", "oz": ["开到他旁边对他大喊", "不理他", "对他闪远光", "报复回去加塞他"], "story": "小猪被别人抢道了，深呼吸，“算啦～”不生气不报复，安全最重要。", "tip": "被加塞：不理他", "tricky": false}, {"id": "ch3-47", "ch": "ch3", "num": 47, "q": "IF SOMEONE IS DRIVING AGGRESSIVELY BEHIND YOU, YOU SHOULD:", "opts": ["Try to get out of the aggressive driver’s way", "Stare at the driver as he or she is passing you", "Speed up as he or she is passing you", "Block the passing lane"], "ans": 0, "qz": "如果有人在你后面激进驾驶，你应该：", "oz": ["尽量让开他的路", "在他超车时盯着他", "在他超车时加速", "堵住超车道"], "story": "后面一辆车凶巴巴地贴着小鸭子，小鸭子靠边让它先走，“你先请～”", "tip": "凶车来了让开", "tricky": false}, {"id": "ch3-48", "ch": "ch3", "num": 48, "q": "FOR AN AVERAGE PERSON, HOW MANY MINUTES DOES THE BODY NEED TO PROCESS THE ALCOHOL IN ONE DRINK?", "opts": ["15", "60", "90", "30"], "ans": 1, "qz": "对普通人来说，身体处理一杯酒中的酒精需要多少分钟？", "oz": ["15", "60", "90", "30"], "story": "小熊喝一杯酒，身体里的小清洁工要忙60分钟（一小时）才能扫干净。", "tip": "一杯酒=一小时", "tricky": true}, {"id": "ch3-49", "ch": "ch3", "num": 49, "q": "__________ LIMIT(S) YOUR CONCENTRATION, PERCEPTION, JUDGMENT, AND MEMORY.", "opts": ["Only a blood alcohol level greater than the legal limit", "Alcohol does not", "Even the smallest amount of alcohol", "Only a blood alcohol level greater than .05"], "ans": 2, "qz": "__________会限制你的注意力、感知、判断和记忆。", "oz": ["只有超过法定上限的血液酒精", "酒精不会", "哪怕最少量的酒精", "只有超过.05的血液酒精"], "story": "一点点酒，小兔子的脑袋就会开始慢慢变迷糊。哪怕一小口也会影响开车。", "tip": "一点点酒就影响", "tricky": false}, {"id": "ch3-50", "ch": "ch3", "num": 50, "q": "TAKING DRUGS ALONG WITH ALCOHOL:", "opts": ["Increases the risk of causing a crash", "Is no more dangerous than alcohol by itself", "Lessens the effect of alcohol on your ability to drive", "Has no effect on your general driving ability"], "ans": 0, "qz": "毒品和酒精一起服用：", "oz": ["增加造成车祸的风险", "不比单独喝酒更危险", "减轻酒精对驾驶的影响", "对驾驶能力没影响"], "story": "药加酒，就像小猫同时被两只手推着摔跤，危险加倍！", "tip": "药+酒=更危险", "tricky": false}, {"id": "ch3-51", "ch": "ch3", "num": 51, "q": "AS ALCOHOL BUILDS UP IN YOUR BLOOD, IT:", "opts": ["Slows down your reactions", "Makes you feel less confident", "Begins to metabolize itself more quickly", "Decreases your driving errors"], "ans": 0, "qz": "随着血液中酒精积累，它会：", "oz": ["减慢你的反应", "让你更没自信", "自己代谢得更快", "减少驾驶错误"], "story": "小狐狸喝了酒，看到红灯脚却慢半拍才踩刹车。酒让反应变慢。", "tip": "酒=反应慢", "tricky": false}, {"id": "ch3-52", "ch": "ch3", "num": 52, "q": "IF YOUR BLOOD ALCOHOL LEVEL IS .04, YOU:", "opts": ["Are 2 – 7 times more likely to have a crash than a person who has not consumed any", "Are above the legal blood alcohol limit but fine to drive", "Can be very sure that you will drive safely", "Should drink plenty of coffee before getting behind the wheel of your car"], "ans": 0, "qz": "如果你的血液酒精浓度是.04，你：", "oz": ["比没喝酒的人出车祸几率高2-7倍", "超过法定上限但可以开车", "可以确定会安全驾驶", "上车前应该喝大量咖啡"], "story": "小熊血液酒精只有0.04，还没到0.08，可是出车祸的几率已经变成2到7倍啦！", "tip": ".04也危险2-7倍", "tricky": true}, {"id": "ch3-53", "ch": "ch3", "num": 53, "q": "WHEN YOU HEAR A FIRE ENGINE SIREN, YOU MUST:", "opts": ["Slow down until it passes you", "Drive with your flashers on", "Pull over to the side of the road and stop", "Speed up and take the nearest exit"], "ans": 2, "qz": "听到消防车警笛时，你必须：", "oz": ["减速直到它过去", "开双闪行驶", "靠边停车", "加速走最近的出口"], "story": "呜哇呜哇消防车来了！小兔子马上靠到路边停下，让消防车去救火🚒。", "tip": "警笛=靠边停", "tricky": false}, {"id": "ch3-54", "ch": "ch3", "num": 54, "q": "IF YOU HAVE A TIRE BLOWOUT, YOU SHOULD:", "opts": ["Allow the steering wheel to move freely", "Let the car slow to a stop", "Continue driving until you reach a garage", "Brake hard to stop the car immediately"], "ans": 1, "qz": "如果爆胎了，你应该：", "oz": ["让方向盘自由转动", "让车慢慢滑停", "继续开到修车厂", "猛踩刹车立刻停车"], "story": "“砰！”小猪的轮胎爆了。它紧紧握住方向盘，不猛踩刹车，松开油门让车慢慢停下来。", "tip": "爆胎：握紧方向，慢慢停", "tricky": true}, {"id": "ch3-55", "ch": "ch3", "num": 55, "q": "IF YOUR CAR BREAKS DOWN ON A HIGHWAY, YOU SHOULD:", "opts": ["Sit in your car and wait for help", "Use your four-way flashers to warn other drivers", "Sound your horn at passing motorists", "Flash your headlights at oncoming traffic"], "ans": 1, "qz": "如果你的车在高速上抛锚，你应该：", "oz": ["坐在车里等救援", "打开双闪警告其他司机", "对路过的车按喇叭", "对对面来车闪大灯"], "story": "小鸭子的车坏在高速上，第一件事打开双闪：“我坏在这里啦，大家绕一绕。”", "tip": "抛锚开双闪", "tricky": false}, {"id": "ch3-56", "ch": "ch3", "num": 56, "q": "WHEN YOU SEE AN EMERGENCY VEHICLE WITH FLASHING LIGHTS, YOU MUST:", "opts": ["Slow down and keep moving in your lane", "Keep driving in your lane", "Pull to the curb and stop", "Stop exactly where you are"], "ans": 2, "qz": "看到闪灯的紧急车辆时，你必须：", "oz": ["减速并在车道内继续行驶", "在车道内继续开", "靠边停车", "原地停车"], "story": "救护车闪着灯来了，小熊开到路边靠边停好，不是停在路中间哦。", "tip": "紧急车：靠边停", "tricky": true}, {"id": "ch3-57", "ch": "ch3", "num": 57, "q": "WHEN DRIVING ON A ONE WAY STREET AND AN EMERGENCY VEHICLE WITH FLASHING LIGHTS IS BEHIND YOUR CAR, YOU:", "opts": ["Drive with your flashers on", "Drive toward the nearest road side and stop", "Speed up and take the nearest exit", "Slow down until the vehicle passes you"], "ans": 1, "qz": "在单行道上，闪灯紧急车辆在你后面时，你：", "oz": ["开双闪行驶", "向最近的路边靠并停车", "加速走最近出口", "减速等它过去"], "story": "单行道上，小兔子往最近的那一边（可能是左边）靠边停车，给救护车让路。", "tip": "单行道：靠最近一边停", "tricky": true}, {"id": "ch3-58", "ch": "ch3", "num": 58, "q": "AFTER AN EMERGENCY VEHICLE PASSES YOU WITH ITS SIREN ON, YOU MUST:", "opts": ["Drive closely to the police car", "Drive as fast as the police car", "Avoid driving closer than 500 feet behind the emergency vehicle", "Drive near the curb very slowly"], "ans": 2, "qz": "紧急车辆鸣笛从你身边经过后，你必须：", "oz": ["紧跟警车", "和警车开一样快", "与紧急车辆保持至少500英尺距离", "贴着路边慢慢开"], "story": "救护车过去了，小狐狸不跟着凑热闹，离它至少500英尺远。", "tip": "跟紧急车≥500尺", "tricky": true}, {"id": "ch3-59", "ch": "ch3", "num": 59, "q": "CRASHES IN WORK ZONES ARE MOST COMMONLY THE RESULT OF:", "opts": ["Tire blow-outs", "Hydroplaning because of water sprayed on the roadway", "Loss of steering control after driving over wet paint", "Carelessness and speeding"], "ans": 3, "qz": "施工区的车祸最常见原因是：", "oz": ["爆胎", "洒水导致打滑", "开过湿油漆失控", "粗心和超速"], "story": "施工区里，小猪开太快又不看路，差点撞到锥桶。施工区出事大多是粗心+超速。", "tip": "施工区：别粗心别快", "tricky": false}, {"id": "ch3-60", "ch": "ch3", "num": 60, "q": "WHEN DRIVING THROUGH A WORK ZONE, IT IS A GOOD SAFETY PRACTICE TO:", "opts": ["Drive close to the vehicle in front of you to keep traffic flowing freely", "Shorten your usual following distance — by about half", "Turn on your cruise control", "Lengthen your usual following distance — by double"], "ans": 3, "qz": "通过施工区时，好的安全做法是：", "oz": ["紧跟前车保持畅通", "跟车距离缩短一半", "开定速巡航", "跟车距离加倍"], "story": "施工区前车随时会停，小鸭子把跟车距离拉长到两倍。", "tip": "施工区跟车距离×2", "tricky": false}, {"id": "ch3-61", "ch": "ch3", "num": 61, "q": "ON TWO-LANE, TWO-WAY STREETS OR HIGHWAYS, YOU SHOULD START LEFT TURNS:", "opts": ["Close to the center line", "Close to the outside line", "In the center of the lane", "Anywhere in the lane"], "ans": 0, "qz": "在双车道双向道路上，左转应从哪里开始？", "oz": ["靠近中心线", "靠近外侧线", "车道中间", "车道任何位置"], "story": "小兔子要左转，先把车靠到中间黄线旁边，再转进去，像贴着中间线走。", "tip": "左转贴中线", "tricky": true}, {"id": "ch3-62", "ch": "ch3", "num": 62, "q": "TO TURN LEFT ON MULTI-LANE STREETS AND HIGHWAYS, YOU SHOULD START FROM:", "opts": ["The middle of the intersection", "The right lane", "The left lane", "Any lane"], "ans": 2, "qz": "在多车道道路上左转，你应该从哪里开始？", "oz": ["路口中间", "右车道", "左车道", "任何车道"], "story": "小熊要左转，就提前到最左边的车道，“左转走左道”。", "tip": "左转走左道", "tricky": false}, {"id": "ch3-63", "ch": "ch3", "num": 63, "q": "ON A TWO-LANE ROAD, YOU MAY PASS ANOTHER VEHICLE ON THE RIGHT WHEN:", "opts": ["Driving on a single lane entrance ramp", "The driver you are passing is travelling slower than the posted speed limit", "Never", "The driver you are passing is making a left turn"], "ans": 3, "qz": "在双车道道路上，什么时候可以从右侧超车？", "oz": ["在单车道入口匝道上", "被超车辆低于限速", "永远不行", "被超车辆正在左转"], "story": "前面小猪停下来等左转，右边还有足够的路面，小狐狸就可以小心从右边过去。", "tip": "前车左转，可右边过", "tricky": true}, {"id": "ch3-64", "ch": "ch3", "num": 64, "q": "TO PASS A SLOWER-MOVING VEHICLE ON A TWO-LANE ROAD YOU MUST:", "opts": ["Not cross the center line", "Flash your lights to oncoming traffic", "Use the shoulder", "Use that lane that belongs to oncoming traffic"], "ans": 3, "qz": "在双车道道路上超越慢车，你必须：", "oz": ["不越过中心线", "对来车闪灯", "使用路肩", "使用对向车道"], "story": "双车道只有一条去一条回，小猫要超车就得借用对面的车道，所以一定要看清对面没车！", "tip": "双车道超车=借对面车道", "tricky": true}, {"id": "ch3-65", "ch": "ch3", "num": 65, "q": "THESE PAVEMENT MARKINGS TELL YOU THAT AT THE INTERSECTION AHEAD:", "opts": ["Center lane traffic may go straight or turn left", "You can only turn right from the center lane", "The center lane mergers into one lane", "Center lane traffic must turn left"], "ans": 0, "img": "img/ch3-65.png", "qz": "这些路面标线告诉你前方路口：", "oz": ["中间车道可以直行或左转", "中间车道只能右转", "中间车道合并为一条", "中间车道必须左转"], "story": "小鸭子看到中间车道画着一个箭头既往前又往左，“我在这条道可以直走，也可以左转！”", "tip": "箭头两个头=两种都行", "tricky": true}, {"id": "ch3-66", "ch": "ch3", "num": 66, "q": "THE MOST IMPORTANT THING TO REMEMBER ABOUT SPEED MANAGEMENT AND CURVES IS TO:", "opts": ["Drive at the posted speed limit as you enter the curve, then slow down at the sharpest part of the curve", "Slow down before you enter the curve", "Accelerate gently before you enter the curve", "Drive at the posted speed limit of the roadway, before, throughout, and after the curve"], "ans": 1, "qz": "关于速度管理和弯道，最重要的是：", "oz": ["按限速进弯，最急处再减速", "进弯前减速", "进弯前轻轻加速", "弯道前中后都按限速行驶"], "story": "小兔子骑小车进弯，先在直路上把速度降下来，在弯里就稳稳的，出弯再慢慢加速。", "tip": "进弯前先减速", "tricky": true}, {"id": "ch3-67", "ch": "ch3", "num": 67, "q": "DRIVERS ENTERING A ROUNDABOUT OR TRAFFIC CIRCLE:", "opts": ["Must stop before entering", "Must yield to drivers in the roundabout or traffic circle", "Have the right of way if they arrive first", "Have the right of way if there are two lanes"], "ans": 1, "qz": "进入环岛或交通圈的司机：", "oz": ["进入前必须停车", "必须让环岛内的车先行", "先到就有优先权", "两条车道时有优先权"], "story": "环岛里的小动物在转圈圈，小熊在外面等一等，让里面的先走，有空隙再进去。", "tip": "进环岛：让里面的车", "tricky": false}, {"id": "ch3-68", "ch": "ch3", "num": 68, "q": "THE LAW GIVES _______ THE RIGHT OF WAY AT INTERSECTIONS.", "opts": ["No one", "Drivers turning left", "Drivers going straight", "Drivers turning right"], "ans": 0, "qz": "法律在路口给_______优先通行权。", "oz": ["没有人", "左转司机", "直行司机", "右转司机"], "story": "兔老师说：法律没有把“先走”送给任何人，只规定谁要“让”。所以大家都要互相让～", "tip": "法律只规定谁让，没人自带先行", "tricky": true}, {"id": "ch3-69", "ch": "ch3", "num": 69, "q": "AT AN INTERSECTION WITH A STOP SIGN, YOU SHOULD STOP AND:", "opts": ["Check your rearview mirror for cars tailgating", "Go when the vehicle ahead of you goes", "Look right first, then left, then right again", "Look left first, then right, then left again"], "ans": 3, "qz": "在有停车标志的路口，你应该停车并：", "oz": ["看后视镜有没有追尾车", "前车走你就走", "先看右再看左再看右", "先看左再看右再看左"], "story": "小猫停在STOP前：先看左（最近的车从左边来），再看右，最后再看一次左。", "tip": "左-右-左", "tricky": true}, {"id": "ch3-70", "ch": "ch3", "num": 70, "q": "WHEN ENTERING A HIGHWAY FROM AN ENTRANCE RAMP, YOU SHOULD GENERALLY:", "opts": ["Enter above the speed of traffic to get ahead", "Enter slowly to avoid other vehicles", "Stop first, then slowly enter traffic", "Accelerate to the speed of traffic"], "ans": 3, "qz": "从入口匝道进入高速时，一般应该：", "oz": ["高于车流速度抢到前面", "慢慢进去避开车辆", "先停车再慢慢进入", "加速到车流速度"], "story": "小狐狸在匝道上踩油门，速度跟高速上的车一样快，再顺顺地钻进车流。", "tip": "上高速：加到车流速度", "tricky": false}, {"id": "ch3-71", "ch": "ch3", "num": 71, "q": "WHEN EXITING A HIGHWAY, YOU SHOULD SLOW DOWN:", "opts": ["On the main road, just before the exit lane", "Once you see the toll booth", "Once you have moved into the exit lane", "When you first see the exit sign"], "ans": 2, "qz": "驶出高速时，你应该在什么时候减速？", "oz": ["在主路上出口车道之前", "看到收费站时", "进入出口车道后", "一看到出口标志就减速"], "story": "小鸭子先打灯换到出口车道，进了出口车道再减速，不在主路上踩刹车挡住后面的车。", "tip": "进了出口道再减速", "tricky": true}, {"id": "ch3-72", "ch": "ch3", "num": 72, "q": "WHEN DRIVING ON A FREEWAY ENTRANCE RAMP, YOU SHOULD LOOK FOR A GAP IN FREEWAY TRAFFIC BY:", "opts": ["Looking in the inside rearview mirror only", "Looking in the sideview mirror only", "Looking in both rearview and sideview mirrors", "Looking in your mirrors and turning your head to look over your shoulder"], "ans": 3, "qz": "在高速入口匝道上，你应该怎样寻找车流空隙？", "oz": ["只看车内后视镜", "只看侧视镜", "看车内和侧视镜", "看镜子并转头从肩膀后看"], "story": "小熊并入高速，看镜子还不够，还要扭头看盲区，把藏起来的车也找出来。", "tip": "并道：镜子+扭头", "tricky": false}, {"id": "ch3-73", "ch": "ch3", "num": 73, "q": "IF YOU WANT TO GET OFF OF A FREEWAY, BUT YOU MISSED YOUR EXIT, YOU SHOULD:", "opts": ["Go to the next exit, and get off of the freeway there", "Make a U-turn through the median", "Pull onto the shoulder and back your car to the exit", "Flag down a police officer for an escort back to your exit"], "ans": 0, "qz": "如果你想下高速却错过了出口，你应该：", "oz": ["到下一个出口下", "从中央隔离带掉头", "在路肩倒车回出口", "拦警察护送回去"], "story": "小兔子错过出口，“没关系～”开到下一个出口再下，绝不倒车掉头。", "tip": "错过出口去下一个", "tricky": false}, {"id": "ch3-74", "ch": "ch3", "num": 74, "q": "YOU ARE WAITING TO TURN LEFT AT A MULTILANE INTERSECTION, AND OPPOSING TRAFFIC IS BLOCKING YOUR VIEW, YOU SHOULD:", "opts": ["Accelerate rapidly when the first lane you need to cross is clear", "Wait until you can see all the lanes you need to cross before going ahead with your turn", "Wait for the opposing driver to wave you across the intersection", "Edge your car into each lane of opposing traffic as soon as it clears"], "ans": 1, "qz": "在多车道路口等左转，对向车流挡住了视线，你应该：", "oz": ["第一条车道空了就猛加速", "等到能看清要穿过的所有车道再转", "等对向司机挥手让你过", "每条车道一空就把车头探进去"], "story": "小猫等左转，对面大卡车挡住视线，后面可能藏着车！它耐心等到所有车道都看清才转。", "tip": "看不全就别转", "tricky": true}, {"id": "ch3-75", "ch": "ch3", "num": 75, "q": "WHEN NO SIGNS, SIGNALS, OR POLICE TELL YOU WHAT TO DO AT AN INTERSECTION, THE LAW STATES THAT:", "opts": ["Drivers on the right must yield to drivers on the left", "There are no laws stating who must yield", "Drivers going straight must yield to drivers turning left at the intersection", "Drivers turning left must yield to drivers going straight through the intersection"], "ans": 3, "qz": "路口没有标志、信号或警察指示时，法律规定：", "oz": ["右边的车让左边的车", "没有法律规定谁让", "直行车让左转车", "左转车让直行车"], "story": "没有灯的路口，小猪要左转，对面小狗直行，小猪先让小狗过去。", "tip": "左转让直行", "tricky": true}, {"id": "ch3-76", "ch": "ch3", "num": 76, "q": "“HIGHWAY HYPNOSIS” IS A DRIVER CONDITION THAT CAN RESULT FROM:", "opts": ["Staring at the roadway for long periods of time", "Frequent rest stops", "Too much sleep the night before your trip", "Short trips on expressways"], "ans": 0, "qz": "“高速公路催眠”是一种可能由什么引起的司机状态？", "oz": ["长时间盯着道路", "经常休息", "出发前一晚睡太多", "在高速上短途行驶"], "story": "小熊在长长直直的高速上一直盯着前面，眼睛越来越呆，像被催眠了。要多转动眼睛、常休息。", "tip": "一直盯路会被“催眠”", "tricky": true}, {"id": "ch3-77", "ch": "ch3", "num": 77, "q": "WHEN PASSING ON A MULTI-LANE HIGHWAY:", "opts": ["Be sure the passing lane is clear", "Pass only on the right", "Watch for oncoming traffic", "There is no need to signal"], "ans": 0, "qz": "在多车道公路上超车时：", "oz": ["确保超车道是空的", "只从右边超", "注意对向来车", "不需要打灯"], "story": "小兔子超车前先确认旁边那条超车道空空的，再打灯过去。", "tip": "超车：超车道要空", "tricky": false}, {"id": "ch3-78", "ch": "ch3", "num": 78, "q": "THE “FOUR-SECOND RULE” REFERS TO HOW ONE SHOULD:", "opts": ["Yield to other cars", "Turn at stop signs", "Follow another car", "Cross an intersection"], "ans": 2, "qz": "“四秒规则”是指如何：", "oz": ["让其他车", "在停车标志转弯", "跟随另一辆车", "通过路口"], "story": "前车经过一棵树，小狐狸数“一千零一、一千零二、一千零三、一千零四”才到那棵树，这就是安全跟车。", "tip": "4秒=跟车距离", "tricky": false}, {"id": "ch3-79", "ch": "ch3", "num": 79, "q": "IT IS BEST TO KEEP A SPACE CUSHION:", "opts": ["Only in back of your vehicle", "Only on the left and right side of your vehicle", "Only in front of the vehicle", "On all sides of the vehicle"], "ans": 3, "qz": "最好在哪里保持安全空间？", "oz": ["只在车后", "只在左右两侧", "只在车前", "车的四周"], "story": "小鸭子的车像被一个大泡泡🫧包着，前后左右都留空间，谁也碰不到它。", "tip": "四周都留空", "tricky": false}, {"id": "ch3-80", "ch": "ch3", "num": 80, "q": "ALLOWING A SPACE CUSHION IS IMPORTANT BECAUSE IT:", "opts": ["Prevents distractions from other vehicles", "Allows you time to react to situations", "Keeps traffic flowing at a safe pace", "Keeps other drivers alert"], "ans": 1, "qz": "保持安全空间很重要，因为它：", "oz": ["防止其他车让你分心", "给你时间应对情况", "让车流保持安全速度", "让其他司机保持警觉"], "story": "空间就是时间！前面突然停车，小熊有空间就有时间踩刹车。", "tip": "空间=反应时间", "tricky": false}, {"id": "ch3-81", "ch": "ch3", "num": 81, "q": "ALLOW A LARGER SPACE CUSHION WHEN STOPPING:", "opts": ["On an up-hill", "At an intersection", "At a stop sign", "At a toll plaza"], "ans": 0, "qz": "在什么情况下停车时要留更大的空间？", "oz": ["上坡时", "在路口", "在停车标志前", "在收费站"], "story": "上坡停车时，前面的车起步可能往后溜，小兔子就停远一点。", "tip": "上坡停车留大空", "tricky": true}, {"id": "ch3-82", "ch": "ch3", "num": 82, "q": "WHEN MAKING A TURN, YOU MUST _____ YOUR SPEED.", "opts": ["Increase", "Maintain", "Vary", "Reduce"], "ans": 3, "qz": "转弯时，你必须_____车速。", "oz": ["提高", "保持", "变化", "降低"], "story": "小猪转弯太快会被甩出去，所以转弯先减速。", "tip": "转弯必减速", "tricky": false}, {"id": "ch3-83", "ch": "ch3", "num": 83, "q": "WHEN DRIVING IN TRAFFIC, IT IS SAFEST TO:", "opts": ["Fluctuate your speed to keep alert", "Drive faster than the flow of traffic", "Drive slower than the flow of traffic", "Drive with the flow of traffic"], "ans": 3, "qz": "在车流中行驶，最安全的是：", "oz": ["忽快忽慢保持警觉", "比车流快", "比车流慢", "跟着车流速度"], "story": "小鸭子跟大家一起游，速度一样，就不会撞来撞去。", "tip": "跟车流同速", "tricky": false}, {"id": "ch3-84", "ch": "ch3", "num": 84, "q": "THE MAXIMUM SPEED LIMIT IN THIS STATE IS ____ MILES PER HOUR .", "opts": ["55", "50", "60", "65"], "ans": 3, "qz": "本州的最高限速是____英里/小时。", "oz": ["55", "50", "60", "65"], "story": "这是题库里的答案：65英里。小熊记住考试按65选。（注：宾州现在部分高速已经可以开到70，但考题答案是65）", "tip": "考试选65", "tricky": true, "flag": "考题答案为65 mph（PDF答案页）。注意：2016年起宾州部分高速限速已提高到70 mph，现行考试以官方题库为准。"}, {"id": "ch3-85", "ch": "ch3", "num": 85, "q": "DRIVE BELOW THE POSTED SPEED LIMIT WHEN:", "opts": ["Anything makes conditions less than perfect", "Others drive below the speed limit", "Entering a highway where there are other cars", "You are on a four lane road"], "ans": 0, "qz": "什么时候应低于标示限速行驶？", "oz": ["任何让路况不完美的情况", "别人都低于限速时", "进入有车的高速时", "在四车道道路上"], "story": "下雨、起雾、天黑、路坑……只要有一点不完美，小兔子就开得比限速慢。", "tip": "不完美就更慢", "tricky": false}, {"id": "ch3-86", "ch": "ch3", "num": 86, "q": "THE AMOUNT OF SPACE YOU NEED TO CROSS TRAFFIC DEPENDS ON THE:", "opts": ["Road and weather conditions and oncoming traffic", "Presence of a stop sign", "Use of your turn signals", "Cars behind you"], "ans": 0, "qz": "穿过车流所需的空间取决于：", "oz": ["道路天气状况和对向车流", "有没有停车标志", "是否使用转向灯", "后面的车"], "story": "下雨路滑、对面车多，小猫需要更大的空隙才能安全穿过。", "tip": "路况天气+来车", "tricky": false}, {"id": "ch3-87", "ch": "ch3", "num": 87, "q": "YOUR ABILITY TO STOP IS AFFECTED BY:", "opts": ["Signal lights", "Other cars on the road", "The time of day", "The condition of the road"], "ans": 3, "qz": "你的停车能力受什么影响？", "oz": ["信号灯", "路上其他车", "时间", "路面状况"], "story": "结冰的路滑溜溜，小熊踩刹车要滑好远。路面状况决定能多快停住。", "tip": "路面决定刹车", "tricky": false}, {"id": "ch3-88", "ch": "ch3", "num": 88, "q": "WHICH OF THE FOLLOWING IS TRUE ABOUT THE SPEED AT WHICH YOU TRAVEL?", "opts": ["The safe speed to drive depends on many conditions", "Driving slowly is always safer", "The speed limit is always a safe speed", "Accelerating is always dangerous"], "ans": 0, "qz": "关于行驶速度，以下哪项正确？", "oz": ["安全速度取决于很多条件", "开慢总是更安全", "限速总是安全速度", "加速总是危险的"], "story": "小狐狸知道：没有一个永远安全的速度，要看天气、路况、车流来决定。", "tip": "安全速度看情况", "tricky": false}, {"id": "ch3-89", "ch": "ch3", "num": 89, "q": "TO PREPARE FOR ANYTHING COMING UP IN THE ROAD AHEAD, YOU SHOULD:", "opts": ["Continually scan the entire road and roadsides", "Stare straight ahead at all times", "Drive with your left foot resting lightly on the brake pedal", "Maintain focus toward the middle of the road"], "ans": 0, "qz": "为了应对前方道路的任何情况，你应该：", "oz": ["持续扫视整个道路和路边", "一直直视前方", "左脚轻放在刹车上", "专注看道路中间"], "story": "小兔子的眼睛像小雷达📡，不停扫前面、两边、路边，早早发现小猫小狗。", "tip": "眼睛要扫来扫去", "tricky": false}, {"id": "ch3-90", "ch": "ch3", "num": 90, "q": "AT HIGHWAY SPEEDS, ON A DRY ROAD, A SAFE FOLLOWING DISTANCE IS AT LEAST:", "opts": ["3 seconds of following distance from the car ahead of you", "2 seconds of following distance from the car ahead of you", "4 seconds of following distance from the car ahead of you", "2 car lengths of following distance from the car ahead of you"], "ans": 2, "qz": "在高速公路干燥路面上，安全跟车距离至少是：", "oz": ["与前车3秒", "与前车2秒", "与前车4秒", "与前车2个车身"], "story": "好天气高速上，小熊也要数到4秒。", "tip": "干路高速也要4秒", "tricky": true}, {"id": "ch3-91", "ch": "ch3", "num": 91, "q": "WHAT CAN YOU DO TO AVOID THE NEED TO MAKE EMERGENCY (OR “PANIC”) STOPS WHILE DRIVING IN TRAFFIC?", "opts": ["Honk your horn to make others aware of your presence", "Look ahead and maintain a safe following distance", "Drive in the right lane only", "Drive slower than the flow of traffic"], "ans": 1, "qz": "怎样避免在车流中紧急刹车？", "oz": ["按喇叭让别人注意你", "向前看并保持安全跟车距离", "只走右车道", "比车流慢"], "story": "小鸭子往远处看，离前车远远的，前面有事早早就知道，不用慌慌张张急刹车。", "tip": "看远+留距离", "tricky": false}, {"id": "ch3-92", "ch": "ch3", "num": 92, "q": "WHEN FACED WITH ONE ONCOMING CAR TO THE LEFT AND A BICYCLIST TO THE RIGHT, YOU SHOULD:", "opts": ["Pull onto the shoulder", "Split the difference", "Let the car pass and then pass the bike", "Pass the bike quickly"], "ans": 2, "qz": "左边有一辆对向车、右边有骑自行车的人时，你应该：", "oz": ["开到路肩上", "从两者中间挤过去", "让车先过去再超自行车", "快速超过自行车"], "story": "小猪左边来车、右边自行车，它先放慢，等对面车过去，再从左边大方超过自行车。一次只对付一个！", "tip": "一次只处理一个危险", "tricky": true}, {"id": "ch3-93", "ch": "ch3", "num": 93, "q": "IF AN ONCOMING DRIVER IS HEADING TOWARD YOU IN YOUR LANE, YOU SHOULD:", "opts": ["Steer right, blow your horn, and accelerate", "Steer left, blow your horn, and brake", "Steer right, blow your horn, and brake", "Stay in the center of your lane, blow your horn, and brake"], "ans": 2, "qz": "对面司机开进你的车道朝你冲来，你应该：", "oz": ["向右打方向、按喇叭、加速", "向左打方向、按喇叭、刹车", "向右打方向、按喇叭、刹车", "待在车道中间、按喇叭、刹车"], "story": "一辆车逆行冲向小兔子！小兔子往右边躲、按喇叭、踩刹车。不往左，因为对方可能也往回躲。", "tip": "迎面冲来：右躲+喇叭+刹车", "tricky": true}, {"id": "ch3-94", "ch": "ch3", "num": 94, "q": "IF THE REAR OF YOUR VEHICLE STARTS TO SKID LEFT, YOU SHOULD:", "opts": ["Steer left", "Hit your brakes", "Accelerate", "Steer right"], "ans": 0, "qz": "如果车尾开始向左打滑，你应该：", "oz": ["向左打方向", "猛踩刹车", "加速", "向右打方向"], "story": "小猫的车屁股往左边甩，它就把方向盘也往左打——“屁股去哪，头就跟去哪”，车就直回来了。", "tip": "车尾往哪滑，方向往哪打", "tricky": true}, {"id": "ch3-95", "ch": "ch3", "num": 95, "q": "THE MOST EFFECTIVE THING YOU CAN DO TO REDUCE YOUR RISK OF GETTING INJURED OR KILLED IN A TRAFFIC CRASH IS:", "opts": ["Wear your seat belt", "Limit your driving to week days", "Stay in the right lane on multi-lane highways", "Limit your driving to times between 3:00 p.m. and 6:00 p.m."], "ans": 0, "qz": "减少在车祸中受伤或死亡风险最有效的方法是：", "oz": ["系安全带", "只在工作日开车", "在多车道公路只走右道", "只在下午3-6点开车"], "story": "小熊每次上车第一件事，“咔哒”系好安全带，像被妈妈抱紧紧。", "tip": "上车先系安全带", "tricky": false}, {"id": "ch3-96", "ch": "ch3", "num": 96, "q": "WHEN DRIVING ON SLICK ROADS, YOU SHOULD:", "opts": ["Take turns more slowly", "Change lanes quickly", "Accelerate quickly", "Brake hard"], "ans": 0, "qz": "在湿滑路面上开车，你应该：", "oz": ["转弯更慢", "快速变道", "快速加速", "猛踩刹车"], "story": "路滑滑的，小鸭子转弯慢慢的，不急变道不猛刹车。", "tip": "滑路慢转弯", "tricky": false}, {"id": "ch3-97", "ch": "ch3", "num": 97, "q": "WHICH OF THE FOLLOWING IS TRUE ABOUT DRIVING ON A WET ROADWAY?", "opts": ["As you drive faster, your tires become less effective", "Water does not affect cars with good tires", "Deeper water is less dangerous", "As you decrease your speed, the roadway becomes more slippery"], "ans": 0, "qz": "关于在湿路上行驶，以下哪项正确？", "oz": ["开得越快，轮胎越没效", "好轮胎不受水影响", "水越深越不危险", "速度降低路面会更滑"], "story": "小狐狸开得越快，轮胎越像在水上滑冰⛸️，抓不住地面。", "tip": "越快轮胎越抓不住", "tricky": true}, {"id": "ch3-98", "ch": "ch3", "num": 98, "q": "WHEN DRIVING ON SLIPPERY ROADS, YOU SHOULD:", "opts": ["Use alternate routes", "Drive as you would on dry roads", "Increase your following distance", "Avoid crossing bridges or intersections"], "ans": 2, "qz": "在湿滑路面上，你应该：", "oz": ["走其他路线", "像干路一样开", "加大跟车距离", "避免过桥和路口"], "story": "滑路刹车要更远才停，小兔子把跟车距离拉大。", "tip": "滑路距离加大", "tricky": false}, {"id": "ch3-99", "ch": "ch3", "num": 99, "q": "WHEN DRIVING ON WET ROADS, YOU SHOULD:", "opts": ["Drive the speed limit", "Drive slightly faster than the speed limit", "Drive 5 to 10 miles below the speed limit", "Stay close to the vehicle ahead"], "ans": 2, "qz": "在湿路上，你应该：", "oz": ["按限速开", "比限速稍快", "比限速慢5到10英里", "紧跟前车"], "story": "下雨啦，小熊比限速慢5-10英里，慢慢开。", "tip": "湿路慢5-10英里", "tricky": true}, {"id": "ch3-100", "ch": "ch3", "num": 100, "q": "WHEN DRIVING ON WET ROADS, YOU SHOULD:", "opts": ["Increase following distance to 5 or 6 seconds", "Decrease following distance to 2 seconds", "Not be concerned about following distance", "Maintain the 4-second following distance rule"], "ans": 0, "qz": "在湿路上，你应该：", "oz": ["把跟车距离加到5或6秒", "把跟车距离减到2秒", "不用担心跟车距离", "保持4秒跟车规则"], "story": "下雨时小猫数到5或6秒，比平时的4秒更多。", "tip": "湿路5-6秒", "tricky": true}, {"id": "ch3-101", "ch": "ch3", "num": 101, "q": "ROADS FREEZE MORE QUICKLY WHEN THEY ARE:", "opts": ["Flat", "Curvy", "In the sun", "Shaded"], "ans": 3, "qz": "什么样的路结冰更快？", "oz": ["平坦的", "弯曲的", "晒太阳的", "背阴的"], "story": "太阳晒不到的阴凉地方，冰冰冷冷，最先结冰❄️。桥面也一样哦。", "tip": "阴凉处先结冰", "tricky": true}, {"id": "ch3-102", "ch": "ch3", "num": 102, "q": "ROADS BECOME VERY SLIPPERY:", "opts": ["When it has been raining for an hour or more", "The day after it rains", "For the first 10 to 15 minutes of a rain storm", "Right after the rain has stopped"], "ans": 2, "qz": "道路变得非常滑是在：", "oz": ["下雨一小时以上后", "雨后第二天", "下雨的前10到15分钟", "雨刚停时"], "story": "刚下雨的10-15分钟，路上的油和灰被雨水泡起来，像抹了肥皂，最滑！", "tip": "刚下雨10-15分钟最滑", "tricky": true}, {"id": "ch3-103", "ch": "ch3", "num": 103, "q": "HYDROPLANING IS USUALLY CAUSED BY:", "opts": ["Excessive stops", "Sudden stops", "Sudden turns", "Excessive speed"], "ans": 3, "qz": "水滑（漂滑）通常由什么引起？", "oz": ["频繁停车", "急停", "急转弯", "速度过快"], "story": "小猪开太快，轮胎来不及把水挤开，就浮在水上像滑水板🏄。", "tip": "水滑=太快", "tricky": false}, {"id": "ch3-104", "ch": "ch3", "num": 104, "q": "HYDROPLANING CAN BE HELPED BY DRIVING:", "opts": ["Through shallow water", "Faster", "Slower", "Through deep water"], "ans": 2, "qz": "开得怎样可以防止水滑？", "oz": ["穿过浅水", "更快", "更慢", "穿过深水"], "story": "慢下来，轮胎有时间把水推开，就能重新抓住地面。", "tip": "防水滑=慢", "tricky": false}, {"id": "ch3-105", "ch": "ch3", "num": 105, "q": "WHEN DRIVING IN FOG, YOU SHOULD USE YOUR _________.", "opts": ["Low beam headlights", "High beam headlights", "Parking lights", "Hazard flashers"], "ans": 0, "qz": "雾中开车，你应该用_________。", "oz": ["近光灯", "远光灯", "示廓灯", "双闪"], "story": "雾里开远光，光会被雾反射回来白茫茫一片。小兔子开近光灯，照得清清楚楚。", "tip": "雾天开近光", "tricky": true}, {"id": "ch3-106", "ch": "ch3", "num": 106, "q": "COMPARED TO DRIVING DURING THE DAY, DRIVING AT NIGHT IS:", "opts": ["Less dangerous", "No more of less dangerous", "More dangerous", "Easier on your eyes"], "ans": 2, "qz": "和白天相比，夜间开车：", "oz": ["更不危险", "一样危险", "更危险", "对眼睛更轻松"], "story": "晚上黑黑的，小熊看不远，所以夜间开车更危险。", "tip": "夜里更危险", "tricky": false}, {"id": "ch3-107", "ch": "ch3", "num": 107, "q": "ANYTHING THAT REQUIRES YOU TO _______ COULD CAUSE YOU TO CRASH.", "opts": ["Take your eyes off the road", "Take your hands off the wheel", "Take your attention away from the driving task", "All of the above"], "ans": 3, "qz": "任何需要你_______的事都可能导致车祸。", "oz": ["视线离开路面", "双手离开方向盘", "注意力离开驾驶", "以上都是"], "story": "眼睛离开、手离开、心离开——三个“离开”都会出事，所以选“以上都是”。", "tip": "三个离开都危险", "tricky": true}, {"id": "ch3-108", "ch": "ch3", "num": 108, "q": "DISTRACTED DRIVERS ARE AT A GREATER RISK OF A CRASH WHEN THEY ARE USING WHICH OF THE FOLLOWING:", "opts": ["CD player", "Radio", "Cell phone", "All of the above"], "ans": 3, "qz": "分心司机在使用以下哪种设备时车祸风险更高？", "oz": ["CD机", "收音机", "手机", "以上都是"], "story": "小狐狸换CD、调收音机、玩手机，都会分心，全都危险！", "tip": "都会分心=全选", "tricky": true}, {"id": "ch3-109", "ch": "ch3", "num": 109, "q": "WHEN YOU ARE IN A LINE OF TRAFFIC THAT IS CROSSING A RAILROAD TRACK THAT HAS NO SIGNALS OR GATES:", "opts": ["You have the right of way and do not need to check for trains", "You may pass slower drivers crossing the track", "You need to make sure there is space to get all the way across the tracks without stopping, before you start to cross", "All of the above"], "ans": 2, "qz": "当你在一列车流中穿过没有信号灯或栏杆的铁轨时：", "oz": ["你有优先权不需要看火车", "可以超过过轨的慢车", "开始过之前要确保对面有足够空间一口气开过去不停车", "以上都是"], "story": "小鸭子过铁轨前先看对面有没有位置，确保能一口气开过去，不会卡在铁轨上。", "tip": "过铁轨不能停在轨上", "tricky": true}, {"id": "ch3-110", "ch": "ch3", "num": 110, "q": "WHEN APPROACHING A STOPPED SCHOOL BUS WITH ITS RED LIGHTS FLASHING AND ITS STOP ARM EXTENDED, YOU MUST:", "opts": ["Stop 5 feet away from the bus", "Stop only if you see children are present", "Stop and remain stopped until it appears safe to proceed", "Stop and remain stopped until the red lights stop flashing and the stop arm has been withdrawn"], "ans": 3, "qz": "接近停着、红灯闪烁且停车臂伸出的校车时，你必须：", "oz": ["在离校车5英尺处停", "看到孩子才停", "停车直到看起来安全", "停车直到红灯停止闪烁、停车臂收回"], "story": "小兔子在校车后面停好，一直等到红灯不闪、STOP小手收回去才走，不能自己觉得“好像安全了”就走。", "tip": "等红灯灭、小手收", "tricky": true}, {"id": "ch4-1", "ch": "ch4", "num": 1, "q": "THE MINIMUM DRINKING AGE IN THIS STATE IS ____ YEARS.", "opts": ["9", "20", "21", "18"], "ans": 2, "qz": "本州的最低饮酒年龄是____岁。", "oz": ["9", "20", "21", "18"], "story": "小兔子要等到21岁生日🎂才能喝酒，宾州规定是21。", "tip": "饮酒21岁", "tricky": false}, {"id": "ch4-2", "ch": "ch4", "num": 2, "q": "PEOPLE UNDER 16 YEARS OF AGE WHO USE A FALSE IDENTIFICATION CARD TO BUY ALCOHOL WILL:", "opts": ["Receive a driving suspension that starts on their 16th birthday", "Not be able to take the driver’s exam until their 21st birthday", "Receive a driving suspension that starts on their 21st birthday", "Be sent to an alcohol safety education class"], "ans": 0, "qz": "16岁以下用假身份证买酒的人会：", "oz": ["驾照暂停从16岁生日开始算", "21岁前不能考驾照", "驾照暂停从21岁生日开始算", "被送去酒精安全教育课"], "story": "小狐狸15岁用假证买酒被抓，还没驾照呢！那就等到16岁生日那天，暂停就开始了，想考驾照得先等罚完。", "tip": "不满16：16岁生日开始罚", "tricky": true}, {"id": "ch4-3", "ch": "ch4", "num": 3, "q": "IF A PERSON UNDER 21 YEARS OLD CONSUMES ALCOHOL, BUT IS NOT DRIVING A MOTOR VEHICLE, THE PENALTY FOR A FIRST OFFENSE IS:", "opts": ["A 90-day driver license suspension and up to a $500 fine", "A 6-month probation", "Sentence to a corrections institution", "Points on the driving record"], "ans": 0, "qz": "21岁以下的人喝酒但没开车，初犯的处罚是：", "oz": ["驾照暂停90天并罚款最多500美元", "6个月缓刑", "送进管教机构", "驾驶记录扣分"], "story": "小熊20岁偷偷喝酒，虽然没开车，也要被暂停驾照90天，还罚最多500块。", "tip": "未满21喝酒：90天+500", "tricky": true}, {"id": "ch4-4", "ch": "ch4", "num": 4, "q": "PARENTAL CONSENT TO CONDUCT BREATH, BLOOD, AND URINE TESTS IS:", "opts": ["Not required", "Required from only one parent", "Required for people under 16 years old", "Required from both parents"], "ans": 0, "qz": "进行呼气、血液和尿液检测需要家长同意吗？", "oz": ["不需要", "只需要一位家长", "16岁以下需要", "需要父母双方"], "story": "警察叔叔要给小猫做检测，不用打电话问妈妈同意，直接做。", "tip": "检测不需家长同意", "tricky": true}, {"id": "ch4-5", "ch": "ch4", "num": 5, "q": "IT IS AGAINST THE LAW FOR ANYONE UNDER THE AGE OF 21 TO ______ ALCOHOL.", "opts": ["Wear clothing advertising", "Be in the presence of", "Consume", "Serve"], "ans": 2, "qz": "21岁以下的人______酒是违法的。", "oz": ["穿印有酒广告的衣服", "在酒旁边", "饮用", "端送"], "story": "小兔子未满21，喝酒是违法的。穿件啤酒T恤不违法哦。", "tip": "未满21：不能喝", "tricky": false}, {"id": "ch4-6", "ch": "ch4", "num": 6, "q": "IT IS AGAINST THE LAW FOR ANYONE UNDER THE AGE OF 21 TO ______ ALCOHOL.", "opts": ["Wear clothing advertising", "Possess", "Serve", "Be in the presence of"], "ans": 1, "qz": "21岁以下的人______酒是违法的。", "oz": ["穿印有酒广告的衣服", "持有", "端送", "在酒旁边"], "story": "小猪包里藏着酒，就算没喝，“拿着”也是违法的。", "tip": "未满21：不能拿", "tricky": false}, {"id": "ch4-7", "ch": "ch4", "num": 7, "q": "IT IS AGAINST THE LAW FOR ANYONE UNDER THE AGE OF 21 TO ______ ALCOHOL.", "opts": ["Serve", "Wear clothing advertising", "Be in the presence of", "Transport"], "ans": 3, "qz": "21岁以下的人______酒是违法的。", "oz": ["端送", "穿印有酒广告的衣服", "在酒旁边", "运送"], "story": "小鸭子开车帮别人运一箱啤酒，未满21也是违法的！", "tip": "未满21：不能运", "tricky": true}, {"id": "ch4-8", "ch": "ch4", "num": 8, "q": "ONE OF THE PENALTIES FOR DRIVING UNDER THE INFLUENCE OF ALCOHOL IS A(N):", "opts": ["5 – year driver’s license suspension", "$100.00 fine", "Attendance to Alcohol Highway Safety School", "12 – hour sentence in jail"], "ans": 2, "qz": "酒驾的处罚之一是：", "oz": ["驾照暂停5年", "罚款100美元", "参加酒精公路安全学校", "在监狱关12小时"], "story": "小狐狸酒驾被抓，要去“酒精公路安全学校”上课，学会再也不酒驾。", "tip": "酒驾要上安全学校", "tricky": true}, {"id": "ch4-9", "ch": "ch4", "num": 9, "q": "IF YOU ARE ARRESTED FOR DRIVING UNDER THE INFLUENCE OF ALCOHOL AND YOU REFUSE TO TAKE THE BLOOD TEST, YOU WILL RECIEVE A:", "opts": ["Drug counseling treatment", "Sentence of one day in jail", "Driver’s License Suspension", "$300.00 fine"], "ans": 2, "qz": "如果你因酒驾被捕并拒绝验血，你会：", "oz": ["接受戒毒治疗", "入狱一天", "驾照被暂停", "罚款300美元"], "story": "小熊不肯验血，“不验？那驾照先收走！”拒绝检测=驾照暂停。", "tip": "拒验=吊照", "tricky": false}, {"id": "ch4-10", "ch": "ch4", "num": 10, "q": "IF A POLICE OFFICER REQUIRES YOU TO TAKE A BLOOD, BREATH, OR URINE TEST, YOU:", "opts": ["May choose the test you prefer", "Must sign a consent form", "May refuse if underage", "Must take the test, or your license will be suspended"], "ans": 3, "qz": "如果警察要求你做血液、呼气或尿液检测，你：", "oz": ["可以选喜欢的检测", "必须签同意书", "未成年可以拒绝", "必须接受，否则驾照被暂停"], "story": "开车就等于答应了：警察要测就得测，不然驾照没了。", "tip": "要测就测", "tricky": false}, {"id": "ch4-11", "ch": "ch4", "num": 11, "q": "FOR A FIRST CONVICTION FOR DRIVING UNDER THE INFLUENCE AT ANY BLOOD ALCOHOL CONCENTRATION LEVEL, YOU COULD:", "opts": ["Lose your license for up to 5 years", "Be required to conduct a public education class on the dangers of drunk driving", "Be required to drive with a restricted occupational license", "Pay a fine of at least $300"], "ans": 3, "qz": "在任何血液酒精浓度下首次酒驾定罪，你可能：", "oz": ["驾照最多吊销5年", "被要求去讲酒驾危害的公开课", "被要求使用限制性工作驾照", "支付至少300美元罚款"], "story": "小猪第一次酒驾，罚款至少300美元起步。", "tip": "初次酒驾≥300元", "tricky": true}, {"id": "ch4-12", "ch": "ch4", "num": 12, "q": "IF UNDER 21 YEARS OF AGE YOU ARE CONSIDERED TO BE DRIVING WHILE UNDER THE INFLUENCE IF YOUR BLOOD ALCOHOL LEVEL IS:", "opts": [".08% or higher", ".10% or higher", ".05% or higher", ".02% or higher"], "ans": 3, "qz": "21岁以下，血液酒精浓度达到多少就算酒驾？", "oz": [".08%或以上", ".10%或以上", ".05%或以上", ".02%或以上"], "story": "大人是0.08，小兔子未满21只要0.02就算酒驾——几乎一滴都不能喝！", "tip": "未满21：0.02", "tricky": true}, {"id": "ch4-13", "ch": "ch4", "num": 13, "q": "IF YOU ARE UNDER AGE 21 AND ARE CONVICTED OF DRIVING UNDER THE INFLUENCE OF ALCOHOL, YOU WILL RECEIVE A ____ LICENSE SUSPENSION FOR A FIRST OFFENSE.", "opts": ["60-Day", "30-Day", "6-Month", "1-Year"], "ans": 3, "qz": "21岁以下被判酒驾，初犯会被暂停驾照____。", "oz": ["60天", "30天", "6个月", "1年"], "story": "小熊未满21酒驾，第一次就要停一整年驾照。", "tip": "未满21酒驾：1年", "tricky": true}, {"id": "ch4-14", "ch": "ch4", "num": 14, "q": "IF YOU ARE UNDER AGE 21, AND ARE CONVICTED OF CARRYING A FALSE ID CARD, YOU WILL BE REQUIRED TO PAY A $500 FINE AND YOUR LICENSE WILL BE SUSPENDED FOR 90 DAYS.", "opts": ["Only if your blood alcohol content (BAC) is .02% or higher", "Even if you were not driving", "Only if you were driving at the time of arrest", "Only if your blood alcohol content (BAC) is .02% or higher and you were driving at the time of arrest"], "ans": 1, "qz": "21岁以下被判持有假身份证，要罚500美元并暂停驾照90天：", "oz": ["只在BAC≥.02%时", "即使你没在开车", "只在被捕时正在开车", "BAC≥.02%且被捕时在开车"], "story": "小猫只是口袋里有假证，没开车也一样罚！", "tip": "假证：不开车也罚", "tricky": true}, {"id": "ch4-15", "ch": "ch4", "num": 15, "q": "THE ZERO TOLERANCE LAW REDUCED THE BLOOD ALCOHOL CONTENT (BAC) FROM .08% TO ____ FOR DRIVERS UNDER 21 TO BE CHARGED WITH DRIVING UNDER THE INFLUENCE.", "opts": [".02%", ".05%", ".07%", ".00%"], "ans": 0, "qz": "零容忍法将21岁以下司机被控酒驾的BAC从.08%降到____。", "oz": [".02%", ".05%", ".07%", ".00%"], "story": "零容忍不是零哦！是0.02。小狐狸记住：“零容忍=零点零二”。", "tip": "零容忍=.02", "tricky": true}, {"id": "ch4-16", "ch": "ch4", "num": 16, "q": "IF YOU ARE STOPPED BY A POLICE OFFICER, YOU SHOULD:", "opts": ["Unbuckle your seat belt and lower your window", "Get your paperwork ready before the officer reaches your car", "Stay in your vehicle with your hands on the steering wheel, and wait for the officer to approach you", "Get out of your car and walk toward the patrol car"], "ans": 2, "qz": "被警察拦下时，你应该：", "oz": ["解开安全带并摇下车窗", "在警察走到车边前把文件准备好", "待在车里，双手放在方向盘上，等警察过来", "下车走向警车"], "story": "小兔子被警察叔叔拦下，乖乖坐在车里，两只手放在方向盘上让叔叔看见，等他过来说话。", "tip": "双手放方向盘，坐着等", "tricky": true}];